export const GRADE_09: readonly GradeQuizItem[] = [
  // math
  { id: "g09-math-001", grade: 9, subject: "math", tier: 1, prompt: "Legyen A = {1; 2; 3; 4} és B = {3; 4; 5}. Hány eleme van az A ∪ B halmaznak?", options: ["5", "7", "2", "4"], correctIndex: 0, explanation: "Az A ∪ B halmaz {1; 2; 3; 4; 5}, tehát 5 eleme van. A közös 3 és 4 csak egyszer számít: 4 + 3 − 2 = 5." },
  { id: "g09-math-002", grade: 9, subject: "math", tier: 1, prompt: "Számold ki: 5⁰ + 2⁻¹", options: ["5,5", "1,5", "0,5", "−5"], correctIndex: 1, explanation: "Bármely nem nulla szám 0. hatványa 1, és 2⁻¹ = 1/2 = 0,5. Így 5⁰ + 2⁻¹ = 1 + 0,5 = 1,5." },
  { id: "g09-math-003", grade: 9, subject: "math", tier: 1, prompt: "Oldd meg: 3x − 7 = 11", options: ["x = 4", "x = −6", "x = 6", "x = 18"], correctIndex: 2, explanation: "Mindkét oldalhoz 7-et adunk: 3x = 18, majd 3-mal osztunk: x = 6. Ellenőrzés: 3 · 6 − 7 = 11." },
  { id: "g09-math-004", grade: 9, subject: "math", tier: 1, prompt: "Mennyi 60 és 84 legnagyobb közös osztója?", options: ["6", "24", "420", "12"], correctIndex: 3, explanation: "60 = 2² · 3 · 5 és 84 = 2² · 3 · 7. A közös prímtényezők szorzata 2² · 3 = 12, ez a legnagyobb közös osztó." },
  { id: "g09-math-005", grade: 9, subject: "math", tier: 1, prompt: "Melyik szám osztható 9-cel?", options: ["2346", "4518", "1234", "7105"], correctIndex: 1, explanation: "Egy szám akkor osztható 9-cel, ha számjegyeinek összege osztható 9-cel. A 4518-nál 4 + 5 + 1 + 8 = 18, ez osztható 9-cel." },
  { id: "g09-math-006", grade: 9, subject: "math", tier: 1, prompt: "Mennyi az y = 2x + 3 függvény értéke az x = 4 helyen?", options: ["11", "14", "9", "8"], correctIndex: 0, explanation: "Behelyettesítünk: y = 2 · 4 + 3 = 8 + 3 = 11. Előbb szorzunk, utána adunk össze." },
  { id: "g09-math-007", grade: 9, subject: "math", tier: 2, prompt: "Mennyi |−8| + |3 − 5|?", options: ["6", "−10", "10", "−6"], correctIndex: 2, explanation: "Az abszolút érték a szám nullától mért távolsága, sosem negatív: |−8| = 8 és |3 − 5| = |−2| = 2, így az összeg 10." },
  { id: "g09-math-008", grade: 9, subject: "math", tier: 2, prompt: "Mennyi 18 és 24 legkisebb közös többszöröse?", options: ["6", "432", "72", "144"], correctIndex: 2, explanation: "18 = 2 · 3² és 24 = 2³ · 3. A legkisebb közös többszörös minden prímtényező legnagyobb hatványát veszi: 2³ · 3² = 72." },
  { id: "g09-math-009", grade: 9, subject: "math", tier: 2, prompt: "Oldd meg: 5(x − 2) = 3x + 4", options: ["x = 3", "x = 7", "x = −3", "x = 1"], correctIndex: 1, explanation: "Zárójelbontás után 5x − 10 = 3x + 4, rendezve 2x = 14, így x = 7. Ellenőrzés: 5 · (7 − 2) = 25 és 3 · 7 + 4 = 25." },
  { id: "g09-math-010", grade: 9, subject: "math", tier: 2, prompt: "Egy háromszög egyik oldala a köré írt körének átmérője. Hány fokos az ezzel az oldallal szemközti szög?", options: ["60°", "45°", "180°", "90°"], correctIndex: 3, explanation: "Thalész tétele szerint ha a háromszög egyik oldala a köré írt kör átmérője, akkor a vele szemközti szög derékszög, vagyis 90°." },
  { id: "g09-math-011", grade: 9, subject: "math", tier: 2, prompt: "Hány átlója van egy konvex nyolcszögnek?", options: ["20", "40", "16", "5"], correctIndex: 0, explanation: "Az n oldalú sokszög átlóinak száma n(n − 3)/2. Nyolcszögnél 8 · 5 / 2 = 20. Kettővel azért osztunk, mert minden átlót mindkét végpontjából számoltunk." },
  { id: "g09-math-012", grade: 9, subject: "math", tier: 2, prompt: "Mennyi 240-nek a 35%-a?", options: ["68", "35", "96", "84"], correctIndex: 3, explanation: "240 egy százaléka 2,4, ezért a 35%-a 35 · 2,4 = 84. Másképp: 240 · 0,35 = 84." },
  { id: "g09-math-013", grade: 9, subject: "math", tier: 3, prompt: "Számold ki: 101² − 99²", options: ["2", "400", "200", "4"], correctIndex: 1, explanation: "Két négyzet különbsége szorzattá alakítható: a² − b² = (a + b)(a − b). Így 101² − 99² = 200 · 2 = 400, nem kell a négyzeteket külön kiszámolni." },
  { id: "g09-math-014", grade: 9, subject: "math", tier: 3, prompt: "Melyik az x² − 9 kifejezés szorzattá alakított alakja?", options: ["(x − 3)²", "x(x − 9)", "(x − 3)(x + 3)", "(x − 9)(x + 1)"], correctIndex: 2, explanation: "Két négyzet különbsége: a² − b² = (a − b)(a + b). Itt a = x és b = 3, így x² − 9 = (x − 3)(x + 3)." },
  { id: "g09-math-015", grade: 9, subject: "math", tier: 3, prompt: "Oldd meg: (x + 1)/2 − (x − 1)/3 = 2", options: ["x = 7", "x = 5", "x = 11", "x = −7"], correctIndex: 0, explanation: "6-tal szorozva: 3(x + 1) − 2(x − 1) = 12, azaz 3x + 3 − 2x + 2 = 12, így x + 5 = 12, vagyis x = 7." },
  { id: "g09-math-016", grade: 9, subject: "math", tier: 3, prompt: "Számold ki: 2⁻² · 4³ : 2⁵", options: ["2", "1/4", "8", "1/2"], correctIndex: 3, explanation: "4³ = 2⁶, így a kitevők: −2 + 6 − 5 = −1. Az eredmény 2⁻¹ = 1/2, mert azonos alapnál szorzáskor összeadjuk, osztáskor kivonjuk a kitevőket." },
  { id: "g09-math-017", grade: 9, subject: "math", tier: 3, prompt: "Mi a −2x + 5 > 11 egyenlőtlenség megoldása?", options: ["x < −3", "x > −3", "x < 3", "x > 3"], correctIndex: 0, explanation: "Kivonunk 5-öt: −2x > 6. Negatív számmal osztva megfordul a relációjel, így x < −3." },
  { id: "g09-math-018", grade: 9, subject: "math", tier: 3, prompt: "Mennyi a (0; 1) és a (2; 7) pontokon átmenő egyenes meredeksége?", options: ["4", "1/3", "3", "6"], correctIndex: 2, explanation: "A meredekség a változások hányadosa: (7 − 1) : (2 − 0) = 6 : 2 = 3. Tehát x egységnyi növekedésekor y 3-mal nő." },
  // math — JBb bővítés (2026-11-16): gyártó → validátor → vak megoldó + tantárgyi audit → javítás
  { id: "g09-math-019", grade: 9, subject: "math", tier: 1, prompt: "Számold ki: (3 + 4)²", options: ["37", "49", "14", "25"], correctIndex: 1, explanation: "Előbb a zárójel: 3 + 4 = 7, majd 7² = 49. A 25 a 3² + 4² összeg, a 14 a 7 · 2 szorzat — a négyzetre emelés nem tagonként működik." },
  { id: "g09-math-020", grade: 9, subject: "math", tier: 1, prompt: "Mennyi |−12| − |5|?", options: ["7", "−7", "17", "−17"], correctIndex: 0, explanation: "Az abszolút érték a szám távolsága a nullától: |−12| = 12 és |5| = 5, így 12 − 5 = 7. A 17 akkor jönne ki, ha összeadnánk a két értéket." },
  { id: "g09-math-021", grade: 9, subject: "math", tier: 1, prompt: "Oldd meg: 4x + 5 = 29", options: ["x = 5", "x = 8,5", "x = 7", "x = 6"], correctIndex: 3, explanation: "Mindkét oldalból 5-öt kivonva 4x = 24, majd 4-gyel osztva x = 6. Ellenőrzés: 4 · 6 + 5 = 29. Az x = 8,5 a hibás előjelű átrendezésből adódik." },
  { id: "g09-math-022", grade: 9, subject: "math", tier: 1, prompt: "Mennyi 72 és 96 legnagyobb közös osztója?", options: ["8", "48", "24", "12"], correctIndex: 2, explanation: "72 = 2³ · 3² és 96 = 2⁵ · 3, a közös prímtényezők legkisebb hatványai: 2³ · 3 = 24. A 12 közös osztó, de nem a legnagyobb; a 48 a 72-t nem osztja." },
  { id: "g09-math-023", grade: 9, subject: "math", tier: 1, prompt: "Melyik szám osztható 3-mal és 4-gyel is?", options: ["90", "84", "81", "64"], correctIndex: 1, explanation: "A 84 számjegyösszege 12 (osztható 3-mal), utolsó két jegye 84 (osztható 4-gyel), így 84 = 12 · 7. A 64 nem osztható 3-mal, a 81 és a 90 pedig 4-gyel nem." },
  { id: "g09-math-024", grade: 9, subject: "math", tier: 1, prompt: "A = {1; 2; 3; 4; 5}, B = {4; 5; 6}. Hány eleme van az A ∩ B halmaznak?", options: ["8", "6", "2", "3"], correctIndex: 2, explanation: "A metszetbe a mindkét halmazban szereplő elemek kerülnek: {4; 5}, tehát 2 eleme van. A 6 az unió elemszáma, a 8 a két elemszám összege." },
  { id: "g09-math-025", grade: 9, subject: "math", tier: 1, prompt: "Hol van az y = 3x − 6 függvény zérushelye?", options: ["x = 2", "x = −6", "x = −2", "x = 6"], correctIndex: 0, explanation: "A zérushelyen a függvényérték nulla: 3x − 6 = 0, ebből 3x = 6, tehát x = 2. Az x = −6 a tengelymetszet előjeles értéke, nem a zérushely." },
  { id: "g09-math-026", grade: 9, subject: "math", tier: 1, prompt: "Hány prímszám van 1 és 20 között?", options: ["9", "7", "10", "8"], correctIndex: 3, explanation: "A prímek: 2, 3, 5, 7, 11, 13, 17, 19 — ez összesen 8 szám. Az 1 nem prím, mert csak egy osztója van; a 9 és a 15 összetett szám." },
  { id: "g09-math-027", grade: 9, subject: "math", tier: 1, prompt: "Számold ki: 2⁵ − 5²", options: ["7", "57", "0", "15"], correctIndex: 0, explanation: "2⁵ = 32 és 5² = 25, így 32 − 25 = 7. A 0 akkor jönne ki, ha a 2 · 5 és az 5 · 2 szorzatot vonnánk ki egymásból; az 57 az összeg." },
  { id: "g09-math-028", grade: 9, subject: "math", tier: 1, prompt: "Mennyi 150-nek a 20%-a?", options: ["15", "50", "75", "30"], correctIndex: 3, explanation: "A 20% az egész ötöde: 150 : 5 = 30, vagy 150 · 0,2 = 30. A 15 a 10%, a 75 az 50% lenne." },
  { id: "g09-math-029", grade: 9, subject: "math", tier: 1, prompt: "Egy háromszög két oldala 3 cm és 8 cm. Mekkora lehet a harmadik?", options: ["11 cm", "7 cm", "5 cm", "4 cm"], correctIndex: 1, explanation: "A harmadik oldal nagyobb a különbségnél (5 cm) és kisebb az összegnél (11 cm), így csak a 7 cm jó. Az 5 cm és a 11 cm esetén a háromszög elfajulna." },
  { id: "g09-math-030", grade: 9, subject: "math", tier: 1, prompt: "Melyik NEM egybevágósági transzformáció?", options: ["tengelyes tükrözés", "elforgatás", "kétszeres nagyítás", "eltolás"], correctIndex: 2, explanation: "Az egybevágósági transzformáció megtartja a méretet és az alakot: ilyen az eltolás, az elforgatás és a tengelyes tükrözés. A kétszeres nagyítás a méretet megváltoztatja." },
  { id: "g09-math-031", grade: 9, subject: "math", tier: 1, prompt: "Számold ki: √(5² + 12²)", options: ["7", "169", "17", "13"], correctIndex: 3, explanation: "5² + 12² = 25 + 144 = 169, és √169 = 13. A 17 a gyök alatti számok összege, a gyököt nem lehet tagonként vonni; a 169 a gyökvonás előtti érték." },
  { id: "g09-math-032", grade: 9, subject: "math", tier: 2, prompt: "Számold ki: 15² − 5²", options: ["210", "200", "100", "250"], correctIndex: 1, explanation: "15² − 5² = (15 − 5)(15 + 5) = 10 · 20 = 200; közvetlenül is 225 − 25 = 200. A 100 a (15 − 5)² értéke, ami nem ugyanaz." },
  { id: "g09-math-033", grade: 9, subject: "math", tier: 2, prompt: "Melyik az (a + 3)² kifejtett alakja?", options: ["a² + 9", "a² + 6a + 6", "a² + 6a + 9", "a² + 3a + 9"], correctIndex: 2, explanation: "(a + b)² = a² + 2ab + b², így (a + 3)² = a² + 2 · 3 · a + 9 = a² + 6a + 9. Az a² + 9 alakból hiányzik a kétszeres szorzat." },
  { id: "g09-math-034", grade: 9, subject: "math", tier: 2, prompt: "Ha x + y = 10 és x − y = 4, mennyi x?", options: ["3", "14", "6", "7"], correctIndex: 3, explanation: "A két egyenletet összeadva 2x = 14, tehát x = 7, és ekkor y = 3. Ellenőrzés: 7 + 3 = 10 és 7 − 3 = 4. A 3 az y értéke." },
  { id: "g09-math-035", grade: 9, subject: "math", tier: 2, prompt: "Mennyi a (2; 1) és a (4; 9) pontokon átmenő egyenes meredeksége?", options: ["4", "1/4", "2", "5"], correctIndex: 0, explanation: "A meredekség az y-változás és az x-változás hányadosa: (9 − 1) : (4 − 2) = 8 : 2 = 4. Az 1/4 a fordított osztás eredménye." },
  { id: "g09-math-036", grade: 9, subject: "math", tier: 2, prompt: "Oldd meg: |x| = 5", options: ["x = 5 vagy x = −5", "x = −5", "x = 5", "x = 25"], correctIndex: 0, explanation: "Két szám van, amely 5 egységre esik a nullától: x = 5 vagy x = −5. Csak az egyiket megadni hiányos megoldás." },
  { id: "g09-math-037", grade: 9, subject: "math", tier: 2, prompt: "Mi a 360 prímtényezős felbontása?", options: ["2³ · 3 · 5", "2² · 3² · 5", "2 · 3² · 5²", "2³ · 3² · 5"], correctIndex: 3, explanation: "360 = 8 · 45 = 2³ · 9 · 5 = 2³ · 3² · 5. A többi szorzat értéke 180, 120 és 450, tehát nem a 360-at adják." },
  { id: "g09-math-038", grade: 9, subject: "math", tier: 2, prompt: "Mennyi 36 és 48 legkisebb közös többszöröse?", options: ["12", "1728", "144", "72"], correctIndex: 2, explanation: "36 = 2² · 3² és 48 = 2⁴ · 3, a legnagyobb kitevőkkel 2⁴ · 3² = 144. A 12 a legnagyobb közös osztó; a 72-t a 48 nem osztja." },
  { id: "g09-math-039", grade: 9, subject: "math", tier: 2, prompt: "A = {1; 2; 3; 4; 5; 6}, B = {2; 4; 6; 8}. Melyik halmaz az A ∖ B?", options: ["{1; 3; 5; 8}", "{1; 3; 5}", "{8}", "{2; 4; 6}"], correctIndex: 1, explanation: "Az A ∖ B halmazba az A azon elemei kerülnek, amelyek B-ben nincsenek: {1; 3; 5}. A {8} a B ∖ A, a {2; 4; 6} a metszet." },
  { id: "g09-math-040", grade: 9, subject: "math", tier: 2, prompt: "Melyik vonalak metszéspontja a háromszög súlypontja?", options: ["a súlyvonalak", "a magasságvonalak", "az oldalfelező merőlegesek", "a szögfelezők"], correctIndex: 0, explanation: "A súlyvonal a csúcsot a szemközti oldal felezőpontjával köti össze; a súlyvonalak közös pontja a súlypont. A magasságvonalak a magasságpontot adják." },
  { id: "g09-math-041", grade: 9, subject: "math", tier: 2, prompt: "Számold ki: 3 · (−4) + (−2)²", options: ["−4", "16", "−16", "−8"], correctIndex: 3, explanation: "3 · (−4) = −12 és (−2)² = 4, így −12 + 4 = −8. A −16 akkor jön ki, ha a (−2)²-t tévesen −4-nek vesszük." },
  { id: "g09-math-042", grade: 9, subject: "math", tier: 2, prompt: "Számold ki: (2/3) · (9/4)", options: ["6", "11/7", "3/2", "8/27"], correctIndex: 2, explanation: "Számlálót a számlálóval, nevezőt a nevezővel szorzunk: 18/12, egyszerűsítve 3/2. A 8/27 a fordított tört szorzatából, a 11/7 a tagonkénti összeadásból jön." },
  { id: "g09-math-043", grade: 9, subject: "math", tier: 2, prompt: "Számold ki: 21 · 19", options: ["409", "399", "389", "401"], correctIndex: 1, explanation: "21 · 19 = (20 + 1)(20 − 1) = 20² − 1² = 400 − 1 = 399. A 401 akkor jön ki, ha az 1²-et hozzáadjuk a kivonás helyett." },
  { id: "g09-math-044", grade: 9, subject: "math", tier: 2, prompt: "Mennyi 7,5-nek a 40%-a?", options: ["3", "4,5", "30", "0,3"], correctIndex: 0, explanation: "7,5 · 0,4 = 3, mert 7,5 tizedrésze 0,75, és ennek négyszerese 3. A 4,5 a maradék 60% lenne, a 0,3 és a 30 tizedesvessző-tévesztés." },
  { id: "g09-math-045", grade: 9, subject: "math", tier: 3, prompt: "Számold ki: 99²", options: ["9701", "9801", "9081", "9891"], correctIndex: 1, explanation: "99² = (100 − 1)² = 10000 − 200 + 1 = 9801. A (100 − 1)² kifejtésében a kétszeres szorzat 200, ezt kell levonni, majd 1-et hozzáadni." },
  { id: "g09-math-046", grade: 9, subject: "math", tier: 3, prompt: "Melyik az x² − 10x + 25 szorzattá alakított alakja?", options: ["(x − 5)²", "(x − 5)(x + 5)", "(x + 5)²", "(x − 25)(x + 1)"], correctIndex: 0, explanation: "A kifejezés teljes négyzet: x² − 2 · 5 · x + 5² = (x − 5)². Az (x − 5)(x + 5) szorzat x² − 25, az (x + 5)² pedig +10x tagot adna." },
  { id: "g09-math-047", grade: 9, subject: "math", tier: 3, prompt: "Ha 2x + y = 11 és x − y = 1, mennyi y?", options: ["4", "5", "3", "2"], correctIndex: 2, explanation: "A két egyenletet összeadva 3x = 12, így x = 4, és ebből y = 4 − 1 = 3. Ellenőrzés: 2 · 4 + 3 = 11. A 4 az x értéke." },
  { id: "g09-math-048", grade: 9, subject: "math", tier: 3, prompt: "Oldd meg: |x − 3| = 5", options: ["x = 8", "x = 8 vagy x = 2", "x = −8 vagy x = 2", "x = 8 vagy x = −2"], correctIndex: 3, explanation: "Az x − 3 értéke 5 vagy −5 lehet: x − 3 = 5-ből x = 8, x − 3 = −5-ből x = −2. Ellenőrzés: |8 − 3| = 5 és |−2 − 3| = 5." },
  { id: "g09-math-049", grade: 9, subject: "math", tier: 3, prompt: "Melyik egyenes megy át a (0; −3) és a (2; 1) pontokon?", options: ["y = 2x − 3", "y = x − 3", "y = 2x + 1", "y = −2x − 3"], correctIndex: 0, explanation: "A meredekség (1 − (−3)) : 2 = 2, a tengelymetszet −3, így y = 2x − 3. Ellenőrzés: x = 2-nél 2 · 2 − 3 = 1." },
  { id: "g09-math-050", grade: 9, subject: "math", tier: 3, prompt: "Melyik vonalak metszéspontja a háromszög köré írt körének középpontja?", options: ["a szögfelezők", "a súlyvonalak", "az oldalfelező merőlegesek", "a magasságvonalak"], correctIndex: 2, explanation: "Az oldalfelező merőleges minden pontja egyenlő távolságra van az oldal két végpontjától, ezért a metszéspontjuk mindhárom csúcstól egyformán messze van." },
  { id: "g09-math-051", grade: 9, subject: "math", tier: 3, prompt: "Melyik vonalak metszéspontja a háromszögbe írt kör középpontja?", options: ["a magasságvonalak", "a belső szögfelezők", "a súlyvonalak", "az oldalfelező merőlegesek"], correctIndex: 1, explanation: "A szögfelező pontjai a szög két szárától egyenlő távolságra vannak, így a belső szögfelezők metszéspontja mindhárom oldaltól egyformán messze esik." },
  { id: "g09-math-052", grade: 9, subject: "math", tier: 3, prompt: "Hány pozitív osztója van a 36-nak?", options: ["6", "8", "12", "9"], correctIndex: 3, explanation: "Az osztók: 1, 2, 3, 4, 6, 9, 12, 18, 36 — ez 9 darab. Képlettel: 36 = 2² · 3², az osztók száma (2 + 1)(2 + 1) = 9." },
  { id: "g09-math-053", grade: 9, subject: "math", tier: 3, prompt: "Ha |A| = 12, |B| = 8 és |A ∩ B| = 5, mennyi |A ∪ B|?", options: ["15", "25", "3", "20"], correctIndex: 0, explanation: "Az unió elemszáma |A| + |B| − |A ∩ B| = 12 + 8 − 5 = 15. A 20 hibás, mert a közös 5 elemet kétszer számolja." },
  { id: "g09-math-054", grade: 9, subject: "math", tier: 3, prompt: "Számold ki: (3/4) : (3/8)", options: ["4", "2", "9/32", "1/2"], correctIndex: 1, explanation: "Törttel úgy osztunk, hogy a reciprokával szorzunk: (3/4) · (8/3) = 24/12 = 2. A 9/32 a két tört szorzata, az 1/2 a fordított osztás." },
  { id: "g09-math-055", grade: 9, subject: "math", tier: 3, prompt: "Számold ki: √(2⁴ · 3²)", options: ["36", "6", "72", "12"], correctIndex: 3, explanation: "2⁴ · 3² = 16 · 9 = 144, és √144 = 12. Másképp: √(2⁴) · √(3²) = 4 · 3 = 12. A 36 akkor jön ki, ha csak a 2⁴ kitevőjét felezzük." },
  { id: "g09-math-056", grade: 9, subject: "math", tier: 3, prompt: "Hány szimmetriatengelye van a szabályos hatszögnek?", options: ["12", "2", "6", "3"], correctIndex: 2, explanation: "A szabályos hatszögnek 3 tengelye halad szemközti csúcsokon és 3 szemközti oldalak felezőpontjain át, összesen 6 szimmetriatengelye van." },
  { id: "g09-math-057", grade: 9, subject: "math", tier: 3, prompt: "Mennyi a 12, a 18 és a 30 legkisebb közös többszöröse?", options: ["6", "90", "360", "180"], correctIndex: 3, explanation: "12 = 2² · 3, 18 = 2 · 3², 30 = 2 · 3 · 5, így 2² · 3² · 5 = 180. A 90-et a 12 nem osztja, a 6 pedig a legnagyobb közös osztó." },
  // english
  { id: "g09-english-001", grade: 9, subject: "english", tier: 1, prompt: "Melyik alak illik a mondatba? I ___ in London since 2020.", options: ["have lived", "lived", "am living", "live"], correctIndex: 0, explanation: "A since + időpont mellett present perfectet használunk: I have lived in London since 2020, vagyis azóta is ott él." },
  { id: "g09-english-002", grade: 9, subject: "english", tier: 1, prompt: "Melyik szó illik a mondatba? You ___ smoke here, it is forbidden.", options: ["don't have to", "mustn't", "needn't", "might"], correctIndex: 1, explanation: "A mustn't tiltást fejez ki: tilos. A don't have to csak azt jelenti, hogy nem szükséges, ez nem illik a tiltáshoz." },
  { id: "g09-english-003", grade: 9, subject: "english", tier: 1, prompt: "Melyik szó illik a mondatba? I enjoy ___ books in the evening.", options: ["to read", "read", "reading", "to reading"], correctIndex: 2, explanation: "Az enjoy után -ing alak áll: I enjoy reading books. Ugyanígy viselkedik például a finish és a mind ige is." },
  { id: "g09-english-004", grade: 9, subject: "english", tier: 1, prompt: "Mit jelent angolul: „boldogság”?", options: ["happily", "unhappy", "happy", "happiness"], correctIndex: 3, explanation: "A happy melléknévből a -ness képzővel főnév lesz: happiness = boldogság. A happily határozószó (boldogan), az unhappy jelentése boldogtalan." },
  { id: "g09-english-005", grade: 9, subject: "english", tier: 1, prompt: "Melyik alak illik a mondatba? My brother is ___ than me.", options: ["tall", "more tall", "tallest", "taller"], correctIndex: 3, explanation: "A than előtt középfok kell. Az egy szótagú tall középfoka -er végződéssel képződik: taller, nem more tall." },
  { id: "g09-english-006", grade: 9, subject: "english", tier: 1, prompt: "Melyik alak illik a mondatba? Yesterday I ___ to the cinema with my friends.", options: ["go", "have gone", "went", "was go"], correctIndex: 2, explanation: "A yesterday lezárt múltbeli időt jelöl, ezért past simple kell. A go rendhagyó ige, múlt ideje went." },
  { id: "g09-english-007", grade: 9, subject: "english", tier: 2, prompt: "Melyik alak illik a mondatba? If it rains tomorrow, we ___ at home.", options: ["would stay", "will stay", "stayed", "would have stayed"], correctIndex: 1, explanation: "Ez első típusú feltételes mondat valós jövőbeli lehetőségről: if + present simple, a főmondatban will: we will stay at home." },
  { id: "g09-english-008", grade: 9, subject: "english", tier: 2, prompt: "Melyik alak illik a mondatba? If I ___ a lot of money, I would buy a big house.", options: ["have", "will have", "would have", "had"], correctIndex: 3, explanation: "Második típusú feltételes mondat (elképzelt helyzet): az if után past simple áll, a főmondatban would. Ezért: If I had a lot of money." },
  { id: "g09-english-009", grade: 9, subject: "english", tier: 2, prompt: "Melyik szó illik a mondatba? She decided ___ a new language.", options: ["learning", "learn", "to learn", "learned"], correctIndex: 2, explanation: "A decide után to + főnévi igenév áll: She decided to learn a new language. Hasonlóan: want to, plan to, hope to." },
  { id: "g09-english-010", grade: 9, subject: "english", tier: 2, prompt: "Mit jelent a „look forward to” kifejezés?", options: ["alig várni valamit", "hátranézni", "keresni valamit", "vigyázni valamire"], correctIndex: 0, explanation: "A look forward to jelentése: alig várni valamit, pl. I'm looking forward to the holiday. A keresni look for, a vigyázni look after." },
  { id: "g09-english-011", grade: 9, subject: "english", tier: 2, prompt: "Mit jelent a „turned down” ebben a mondatban? She turned down the job offer.", options: ["elfogadta", "elutasította", "megkereste", "félbehagyta"], correctIndex: 1, explanation: "A turn down itt azt jelenti: elutasít. She turned down the job offer = elutasította az állásajánlatot." },
  { id: "g09-english-012", grade: 9, subject: "english", tier: 2, prompt: "Melyik alak illik a mondatba? While I ___ TV, the phone rang.", options: ["watch", "have watched", "was watching", "am watching"], correctIndex: 2, explanation: "A folyamatban lévő múltbeli cselekvést past continuous fejezi ki, ezt szakítja meg a rövid esemény: While I was watching TV, the phone rang." },
  { id: "g09-english-013", grade: 9, subject: "english", tier: 3, prompt: "Melyik alak illik a mondatba? By the time we arrived, the film ___.", options: ["had already started", "has already started", "already starts", "will have started"], correctIndex: 0, explanation: "Egy múltbeli pillanat előtt már befejeződött cselekvést past perfect fejez ki: the film had already started, mire megérkeztünk." },
  { id: "g09-english-014", grade: 9, subject: "english", tier: 3, prompt: "Melyik szó illik a mondatba? He isn't answering the phone. He ___ be asleep, but I'm not sure.", options: ["must", "can't", "has to", "might"], correctIndex: 3, explanation: "A might bizonytalan lehetőséget fejez ki, ez illik a but I'm not sure részhez. A must biztos következtetést, a can't kizárást jelentene." },
  { id: "g09-english-015", grade: 9, subject: "english", tier: 3, prompt: "Melyik szó illik a mondatba? This old knife is completely ___, it can't cut anything.", options: ["useful", "useless", "usefulness", "uselessly"], correctIndex: 1, explanation: "A -less képző hiányt jelent: useless = haszontalan. A mondat szerint a kés semmit sem vág, és melléknév kell, nem főnév vagy határozószó." },
  { id: "g09-english-016", grade: 9, subject: "english", tier: 3, prompt: "Melyik alak illik a mondatba? If I were you, I ___ that jacket.", options: ["won't buy", "don't buy", "wouldn't buy", "didn't buy"], correctIndex: 2, explanation: "Az If I were you tanácsadó, második típusú feltételes szerkezet, ezért a főmondatban would áll: I wouldn't buy that jacket." },
  { id: "g09-english-017", grade: 9, subject: "english", tier: 3, prompt: "Melyik alak illik a mondatba? This time next week we ___ on the beach.", options: ["will be lying", "lie", "are lain", "have lain"], correctIndex: 0, explanation: "Egy jövőbeli időpontban folyamatban lévő cselekvést future continuous fejez ki: will be + -ing, tehát we will be lying on the beach." },
  { id: "g09-english-018", grade: 9, subject: "english", tier: 3, prompt: "Melyik alak illik a mondatba? I'm not used to ___ up so early.", options: ["get", "getting", "got", "to get"], correctIndex: 1, explanation: "A be used to (hozzászokott valamihez) után a to elöljárószó, ezért -ing alak következik: I'm not used to getting up so early." },
  // english — JBb bővítés (2026-11-16): gyártó → validátor → vak megoldó + tantárgyi audit → javítás
  { id: "g09-english-019", grade: 9, subject: "english", tier: 1, prompt: "Melyik illik a mondatba? The teacher told us ___ quiet.", options: ["be", "being", "to be", "are"], correctIndex: 2, explanation: "Függő beszédben a felszólítást a tell + valaki + to + főnévi igenév szerkezet adja vissza: told us to be quiet. A puszta be, a being és az are itt helytelen." },
  { id: "g09-english-020", grade: 9, subject: "english", tier: 1, prompt: "Melyik illik a mondatba? You ___ wear a seatbelt. It's the law.", options: ["have to", "don't have to", "needn't", "mustn't"], correctIndex: 0, explanation: "Külső szabály (törvény) miatti kötelezettséget a have to fejez ki. A don't have to és a needn't azt jelentené, hogy nem kötelező, a mustn't pedig tiltást." },
  { id: "g09-english-021", grade: 9, subject: "english", tier: 1, prompt: "Melyik illik a mondatba? I want ___ a doctor one day.", options: ["becoming", "became", "become", "to become"], correctIndex: 3, explanation: "A want után to + főnévi igenév áll: want to become. Az -ing alak (becoming) és a puszta ige a want után nyelvtanilag hibás." },
  { id: "g09-english-022", grade: 9, subject: "english", tier: 1, prompt: "Melyik illik a mondatba? She finished ___ her homework at six.", options: ["do", "doing", "did", "to do"], correctIndex: 1, explanation: "A finish ige után -ing alak következik: finished doing. A to do itt hibás, mert a finish nem áll főnévi igenévvel." },
  { id: "g09-english-023", grade: 9, subject: "english", tier: 1, prompt: "Melyik illik a mondatba? You look ill. You ___ see a doctor.", options: ["shouldn't", "couldn't", "needn't", "should"], correctIndex: 3, explanation: "Tanácsot a should fejez ki: ha valaki betegnek látszik, should see a doctor. A shouldn't és a needn't éppen az ellenkezőjét tanácsolná." },
  { id: "g09-english-024", grade: 9, subject: "english", tier: 1, prompt: "Mit jelent angolul: „környezet” (természeti)?", options: ["environment", "experiment", "government", "equipment"], correctIndex: 0, explanation: "A természeti környezet angolul environment. A government kormány, az equipment felszerelés, az experiment kísérlet." },
  { id: "g09-english-025", grade: 9, subject: "english", tier: 1, prompt: "Mit jelent angolul: „erdő”?", options: ["field", "valley", "forest", "hill"], correctIndex: 2, explanation: "Az erdő angolul forest. A field mező, szántóföld, a valley völgy, a hill domb." },
  { id: "g09-english-026", grade: 9, subject: "english", tier: 1, prompt: "Mit jelent angolul: „félelem”?", options: ["joy", "fear", "pride", "anger"], correctIndex: 1, explanation: "A félelem angolul fear. Az anger düh, a pride büszkeség, a joy öröm." },
  { id: "g09-english-027", grade: 9, subject: "english", tier: 1, prompt: "Mit jelent angolul: „tudós” (kutató)?", options: ["science", "scientific", "sciences", "scientist"], correctIndex: 3, explanation: "A tudós, kutató személy angolul scientist. A science tudomány, a scientific tudományos, a sciences a tudományok többes száma." },
  { id: "g09-english-028", grade: 9, subject: "english", tier: 1, prompt: "Melyik illik a mondatba? Please ___ the music, it's too loud.", options: ["turn up", "turn around", "turn down", "turn into"], correctIndex: 2, explanation: "A turn down a hangerő lehalkítását jelenti, ezt kérjük, ha túl hangos a zene. A turn up éppen felhangosítást jelentene." },
  { id: "g09-english-029", grade: 9, subject: "english", tier: 1, prompt: "Melyik illik a mondatba? I can't find my keys. Can you help me ___ them?", options: ["look for", "look like", "look forward", "look after"], correctIndex: 0, explanation: "A look for jelentése keres valamit; elveszett kulcsot keresünk. A look after vigyáz valakire, a look like hasonlít valamire." },
  { id: "g09-english-030", grade: 9, subject: "english", tier: 1, prompt: "Mit jelent angolul: „büszke”?", options: ["brave", "proud", "loud", "shy"], correctIndex: 1, explanation: "A büszke angolul proud. A loud hangos, a brave bátor, a shy félénk." },
  { id: "g09-english-031", grade: 9, subject: "english", tier: 1, prompt: "Melyik illik a mondatba? Do you mind ___ the window?", options: ["open", "opened", "to open", "opening"], correctIndex: 3, explanation: "A mind ige után -ing alak áll: Do you mind opening the window? A to open itt hibás, mert a mind nem áll főnévi igenévvel." },
  { id: "g09-english-032", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? When we got to the station, the train ___.", options: ["had left", "has left", "will leave", "leaves"], correctIndex: 0, explanation: "A vonat korábban ment el, mint ahogy odaértünk, ezért a régebbi múltat past perfect fejezi ki: had left. A has left jelen idejű szerkezet." },
  { id: "g09-english-033", grade: 9, subject: "english", tier: 2, prompt: "„I am busy today,” said Tom. → Tom said he ___ busy that day.", options: ["being", "was", "be", "is"], correctIndex: 1, explanation: "Függő beszédben a jelen idő múltba tolódik (am → was), a today pedig that day lesz, mert már nem ugyanaz a nap: he was busy that day." },
  { id: "g09-english-034", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? He asked me ___ I liked jazz.", options: ["what", "do", "that", "if"], correctIndex: 3, explanation: "Függő eldöntendő kérdést if vagy whether vezet be: He asked me if I liked jazz. A that kijelentést vezet be, a what kiegészítendő kérdést." },
  { id: "g09-english-035", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? If you had studied, you ___ the test last week.", options: ["would pass", "had passed", "would have passed", "will pass"], correctIndex: 2, explanation: "Múltbeli, meg nem valósult feltétel: if + past perfect, a főmondatban would have + 3. alak, tehát would have passed. A last week miatt a would pass nem jó." },
  { id: "g09-english-036", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? The lights are on. They ___ be at home.", options: ["needn't", "don't have to", "must", "mustn't"], correctIndex: 2, explanation: "Biztos következtetést a must fejez ki: ég a villany, tehát must be at home. A mustn't tiltás, a needn't és a don't have to szükségtelenséget jelent." },
  { id: "g09-english-037", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? You ___ bring food; there will be plenty.", options: ["must", "should", "have to", "don't have to"], correctIndex: 3, explanation: "Ha lesz bőven étel, nem szükséges hozni: ezt a don't have to fejezi ki. A have to és a must kötelezettséget, a should tanácsot jelentene." },
  { id: "g09-english-038", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? I've given up ___ sugar.", options: ["to eat", "eating", "eat", "ate"], correctIndex: 1, explanation: "A give up (abbahagy, leszokik valamiről) után -ing alak áll: I've given up eating sugar. Ebben a finish, az avoid és a mind igéhez hasonlít; to + főnévi igenév nem állhat utána." },
  { id: "g09-english-039", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? They agreed ___ us at the station.", options: ["to meet", "meeting", "met", "meet"], correctIndex: 0, explanation: "Az agree után to + főnévi igenév áll: agreed to meet us. Az -ing alak (meeting) az agree után hibás." },
  { id: "g09-english-040", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? She is good at ___ problems.", options: ["solving", "to solve", "solve", "solved"], correctIndex: 0, explanation: "Elöljárószó (at) után az ige -ing alakban áll: good at solving problems. A to solve és a puszta solve az at után nyelvtanilag hibás." },
  { id: "g09-english-041", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? I ran ___ an old friend in town yesterday.", options: ["out", "off", "away", "into"], correctIndex: 3, explanation: "A run into valaki jelentése: véletlenül összefut valakivel. A ran away elszaladt, a ran out kifogyott — tárggyal egyik sem illik ide." },
  { id: "g09-english-042", grade: 9, subject: "english", tier: 2, prompt: "Mit jelent: „to come up with (an idea)”?", options: ["elhalaszt valamit", "előáll (egy ötlettel)", "lemond valamiről", "vigyáz valamire"], correctIndex: 1, explanation: "A come up with jelentése kitalál, előáll valamivel, például egy ötlettel vagy tervvel. A vigyáz valamire a look after, az elhalaszt a put off." },
  { id: "g09-english-043", grade: 9, subject: "english", tier: 2, prompt: "Mit jelent angolul: „csalódott”?", options: ["ashamed", "delighted", "disappointed", "relieved"], correctIndex: 2, explanation: "A csalódott angolul disappointed. A delighted elragadtatott, a relieved megkönnyebbült, az ashamed szégyenkező." },
  { id: "g09-english-044", grade: 9, subject: "english", tier: 2, prompt: "Melyik illik a mondatba? My parents ___ married for ten years when I was born.", options: ["have been", "had been", "will be", "are"], correctIndex: 1, explanation: "A születésem előtti időszakig tartó állapotot past perfect fejezi ki: had been married for ten years. A have been a jelenig tartó állapot." },
  { id: "g09-english-045", grade: 9, subject: "english", tier: 3, prompt: "Melyik illik a mondatba? She was nervous because she ___ never flown before.", options: ["did", "has", "was", "had"], correctIndex: 3, explanation: "A korábbi élményt a múltbeli izgalomhoz képest past perfect fejezi ki: had never flown before. A has a jelenhez viszonyítana." },
  { id: "g09-english-046", grade: 9, subject: "english", tier: 3, prompt: "„Don't touch it!” → He told me ___ it.", options: ["don't touch", "didn't touch", "not to touch", "no touching"], correctIndex: 2, explanation: "Tagadó felszólítás függő beszédben: tell + valaki + not to + ige, tehát told me not to touch it. A don't touch és a didn't touch szerkezet a told me után nem illeszthető." },
  { id: "g09-english-047", grade: 9, subject: "english", tier: 3, prompt: "Melyik illik a mondatba? If she ___ the bus, she wouldn't have been late.", options: ["hadn't missed", "wouldn't miss", "hasn't missed", "didn't miss"], correctIndex: 0, explanation: "A harmadik feltételes mondat if-ága past perfect: if she hadn't missed the bus. A főmondat (wouldn't have been) ehhez illeszkedik." },
  { id: "g09-english-048", grade: 9, subject: "english", tier: 3, prompt: "Melyik mondat harmadik feltételes (third conditional)?", options: ["If I knew, I would have come.", "If I had known, I would have come.", "If I know, I will come.", "If I knew, I would come."], correctIndex: 1, explanation: "A third conditional szerkezete if + past perfect és would have + 3. alak: If I had known, I would have come. A többi első, második vagy vegyes típus." },
  { id: "g09-english-049", grade: 9, subject: "english", tier: 3, prompt: "Melyik illik a mondatba? Take an umbrella. It ___ rain later.", options: ["mustn't", "needn't", "ought", "might"], correctIndex: 3, explanation: "Bizonytalan lehetőséget a might fejez ki: lehet, hogy esni fog. A mustn't tiltás, az ought pedig csak to-val állna (ought to)." },
  { id: "g09-english-050", grade: 9, subject: "english", tier: 3, prompt: "Melyik illik a mondatba? She avoided ___ the question.", options: ["to answer", "answer", "answering", "answered"], correctIndex: 2, explanation: "Az avoid ige után -ing alak áll: avoided answering the question. A to answer az avoid után nyelvtanilag hibás." },
  { id: "g09-english-051", grade: 9, subject: "english", tier: 3, prompt: "Melyik illik a mondatba? I'd rather ___ at home tonight.", options: ["to stay", "stay", "staying", "stayed"], correctIndex: 1, explanation: "A would rather után to nélküli főnévi igenév áll, ha a saját választásunkról beszélünk: I'd rather stay at home. A to stay itt hibás." },
  { id: "g09-english-052", grade: 9, subject: "english", tier: 3, prompt: "Melyik illik a mondatba? The meeting has been put ___ until next week.", options: ["off", "up", "in", "on"], correctIndex: 0, explanation: "A put off jelentése elhalaszt: a megbeszélést a jövő hétre halasztották, tehát put off. A put on felvesz, a put up felállít." },
  { id: "g09-english-053", grade: 9, subject: "english", tier: 3, prompt: "Melyik illik a mondatba? Our car broke ___ on the motorway.", options: ["down", "up", "in", "out"], correctIndex: 0, explanation: "Járműre a break down jelentése: lerobban, leáll. A break up szakítást, a break out kitörést jelent, a break in betörést." },
  { id: "g09-english-054", grade: 9, subject: "english", tier: 3, prompt: "Mit jelent angolul: „választás” (szavazás)?", options: ["reflection", "selection", "election", "collection"], correctIndex: 2, explanation: "A szavazásos választás angolul election. A selection kiválogatás, a collection gyűjtemény, a reflection tükröződés." },
  { id: "g09-english-055", grade: 9, subject: "english", tier: 3, prompt: "Mit jelent angolul: „kísérlet” (tudományos)?", options: ["expedition", "expert", "experience", "experiment"], correctIndex: 3, explanation: "A tudományos kísérlet angolul experiment. Az experience tapasztalat, az expedition expedíció, az expert szakértő." },
  { id: "g09-english-056", grade: 9, subject: "english", tier: 3, prompt: "Mit jelent angolul: „szennyezés” (környezeti)?", options: ["population", "pollution", "pollen", "solution"], correctIndex: 1, explanation: "A környezetszennyezés angolul pollution. A population népesség, a solution megoldás, a pollen virágpor." },
  { id: "g09-english-057", grade: 9, subject: "english", tier: 3, prompt: "„I saw her yesterday,” he said. → He said he had seen her the day ___.", options: ["ago", "later", "after", "before"], correctIndex: 3, explanation: "Függő beszédben a yesterday helyett the day before áll: He said he had seen her the day before. A the day after másnapot jelentene." },
  // hungarian
  { id: "g09-hungarian-001", grade: 9, subject: "hungarian", tier: 1, prompt: "Mi a neve a kommunikációs folyamatban az üzenet küldőjének?", options: ["adó", "vevő", "csatorna", "kód"], correctIndex: 0, explanation: "Az üzenetet az adó küldi, a vevő fogadja. A csatorna az út, amelyen az üzenet halad, a kód pedig a közös jelrendszer." },
  { id: "g09-hungarian-002", grade: 9, subject: "hungarian", tier: 1, prompt: "Kinek tulajdonítja a hagyomány az Iliászt és az Odüsszeiát?", options: ["Szophoklész", "Szapphó", "Homérosz", "Vergilius"], correctIndex: 2, explanation: "A két nagy görög eposzt, az Iliászt és az Odüsszeiát a hagyomány Homérosznak tulajdonítja. Szophoklész drámaíró, Vergilius római költő volt." },
  { id: "g09-hungarian-003", grade: 9, subject: "hungarian", tier: 1, prompt: "Melyik az első összefüggő magyar nyelvű szövegemlékünk?", options: ["Ómagyar Mária-siralom", "Halotti beszéd és könyörgés", "Szabács viadala", "Königsbergi töredék"], correctIndex: 1, explanation: "Az első összefüggő magyar nyelvű szövegemlékünk a Halotti beszéd és könyörgés (1192–1195 körül). Az Ómagyar Mária-siralom az első fennmaradt magyar vers." },
  { id: "g09-hungarian-004", grade: 9, subject: "hungarian", tier: 1, prompt: "Ki a görög mitológiában az istenek királya, az Olümposz ura?", options: ["Poszeidón", "Hermész", "Apollón", "Zeusz"], correctIndex: 3, explanation: "Zeusz a főisten, az ég és a villám ura, az olümposzi istenek királya. Poszeidón a tenger istene, Hermész az istenek hírnöke." },
  { id: "g09-hungarian-005", grade: 9, subject: "hungarian", tier: 1, prompt: "Hány evangélium található az Újszövetségben?", options: ["három", "öt", "négy", "tizenkettő"], correctIndex: 2, explanation: "Az Újszövetségben négy evangélium van: Máté, Márk, Lukács és János evangéliuma. Ezek Jézus életéről és tanításáról szólnak." },
  { id: "g09-hungarian-006", grade: 9, subject: "hungarian", tier: 1, prompt: "Milyen szóelem a „-ban” a „házakban” szóban?", options: ["rag", "képző", "jel", "szótő"], correctIndex: 0, explanation: "A -ban rag, mert mondatbeli viszonyt (helyet) fejez ki, és a szó végére kerül. A házakban szóban a ház a szótő, az -ak a többes szám jele." },
  { id: "g09-hungarian-007", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik Szophoklész-tragédia címszereplője temeti el bátyját, Polüneikészt a király tilalma ellenére?", options: ["Oidipusz király", "Élektra", "Antigoné", "Médeia"], correctIndex: 2, explanation: "Antigoné az isteni törvényt követve eltemeti bátyját, Polüneikészt, bár Kreón király ezt megtiltotta. A Médeia Euripidész műve." },
  { id: "g09-hungarian-008", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik ókori görög költőnő élt Leszbosz szigetén?", options: ["Antigoné", "Pénelopé", "Athéné", "Szapphó"], correctIndex: 3, explanation: "Szapphó a Kr. e. 7–6. században élt Leszbosz szigetén, a görög líra egyik legnagyobb alakja. Antigoné és Pénelopé irodalmi szereplők, Athéné istennő." },
  { id: "g09-hungarian-009", grade: 9, subject: "hungarian", tier: 2, prompt: "Ki az Odüsszeia főhőse, aki a trójai háború után tíz évig bolyong hazafelé Ithakába?", options: ["Akhilleusz", "Odüsszeusz", "Hektór", "Agamemnón"], correctIndex: 1, explanation: "Az Odüsszeia főhőse Odüsszeusz, Ithaka királya, aki a trójai háború után tíz év bolyongás után ér haza feleségéhez, Pénelopéhoz." },
  { id: "g09-hungarian-010", grade: 9, subject: "hungarian", tier: 2, prompt: "Mi a nyelv legkisebb, önálló jelentést hordozó egysége?", options: ["hang", "szóelem", "mondat", "szöveg"], correctIndex: 1, explanation: "A hangnak nincs önálló jelentése, csak jelentést megkülönböztet. A legkisebb jelentéshordozó egység a szóelem (morféma), pl. a ház szótő vagy a -ban rag." },
  { id: "g09-hungarian-011", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik bibliai könyvben olvasható a világ teremtésének története?", options: ["Jelenések könyve", "Máté evangéliuma", "Teremtés könyve", "Apostolok cselekedetei"], correctIndex: 2, explanation: "A teremtéstörténet az Ószövetség első könyvében, a Teremtés könyvében (Mózes első könyvében) olvasható. A többi felsorolt könyv az Újszövetség része." },
  { id: "g09-hungarian-012", grade: 9, subject: "hungarian", tier: 2, prompt: "Hány fő részből áll Dante Isteni színjátéka?", options: ["kettő", "három", "négy", "öt"], correctIndex: 1, explanation: "Az Isteni színjáték három részből áll: Pokol, Purgatórium és Paradicsom. A hármas szám a mű egész szerkezetét meghatározza." },
  { id: "g09-hungarian-013", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik helyesírási elv érvényesül abban, hogy a „barácság” kiejtésű szót „barátság” alakban írjuk?", options: ["kiejtés szerinti írásmód", "szóelemző írásmód", "hagyomány szerinti írásmód", "egyszerűsítő írásmód"], correctIndex: 1, explanation: "A szóelemző írásmód szerint a szóelemeket eredeti alakjukban írjuk: a barát tő és a -ság képző megmarad, bár kiejtve barácság." },
  { id: "g09-hungarian-014", grade: 9, subject: "hungarian", tier: 3, prompt: "Ki kalauzolja Dantét a Pokolban és a Purgatóriumban az Isteni színjátékban?", options: ["Beatrice", "Homérosz", "Vergilius", "Szent Péter"], correctIndex: 2, explanation: "A Pokolban és a Purgatóriumban Vergilius, a római költő, az emberi értelem jelképe vezeti Dantét. A Paradicsomban Beatrice veszi át a kalauzolást." },
  { id: "g09-hungarian-015", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik szövegemlék szólaltatja meg a kereszt alatt álló Mária fájdalmát, és az első fennmaradt magyar nyelvű vers?", options: ["Halotti beszéd és könyörgés", "Königsbergi töredék", "Gesta Hungarorum", "Ómagyar Mária-siralom"], correctIndex: 3, explanation: "Az Ómagyar Mária-siralom (1300 körül) planctus, azaz siralom: Mária fájdalmát szólaltatja meg fia keresztre feszítésekor. Az első fennmaradt magyar vers." },
  { id: "g09-hungarian-016", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik hős haragjának megéneklésével kezdődik az Iliász?", options: ["Hektór", "Odüsszeusz", "Parisz", "Akhilleusz"], correctIndex: 3, explanation: "Az Iliász Akhilleusz haragjával indul: a hős Agamemnónra haragszik meg, és visszavonul a harctól. Hektór a trójaiak hőse, akit később Akhilleusz megöl." },
  { id: "g09-hungarian-017", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik hangtörvény érvényesül a „fűzte” szó kiejtésében, ahol z helyett sz-t ejtünk?", options: ["zöngésség szerinti részleges hasonulás", "teljes hasonulás", "összeolvadás", "rövidülés"], correctIndex: 0, explanation: "A zöngés z a zöngétlen t előtt zöngétlenné válik: fűzte kiejtése fűszte. Ez a zöngésség szerinti részleges hasonulás, a hang csak egy tulajdonságában változik." },
  { id: "g09-hungarian-018", grade: 9, subject: "hungarian", tier: 3, prompt: "Ki a thébai király Szophoklész Antigoné című tragédiájában, aki megtiltja Polüneikész eltemetését?", options: ["Kreón", "Oidipusz", "Haimón", "Teiresziász"], correctIndex: 0, explanation: "Kreón, Théba királya tiltja meg Polüneikész eltemetését, és halálra ítéli Antigonét. Haimón Kreón fia, Teiresziász a vak jós." },
  // hungarian — JBb bővítés (2026-11-16): gyártó → validátor → vak megoldó + tantárgyi audit → javítás
  { id: "g09-hungarian-019", grade: 9, subject: "hungarian", tier: 1, prompt: "Hány énekből áll Homérosz Iliásza?", options: ["tizenkettő", "tíz", "harminchat", "huszonnégy"], correctIndex: 3, explanation: "Az Iliász huszonnégy énekből álló, daktilikus hexameterben írt eposz. Tizenkét énekből Vergilius Aeneise áll." },
  { id: "g09-hungarian-020", grade: 9, subject: "hungarian", tier: 1, prompt: "Ki Odüsszeusz hűséges felesége az Odüsszeiában?", options: ["Antigoné", "Pénelopé", "Kirké", "Helené"], correctIndex: 1, explanation: "Odüsszeusz felesége Pénelopé, aki húsz évig várja haza férjét Ithakában. Helené Menelaosz felesége, Kirké varázslónő." },
  { id: "g09-hungarian-021", grade: 9, subject: "hungarian", tier: 1, prompt: "Hogy hívják Odüsszeusz fiát?", options: ["Télemakhosz", "Patroklosz", "Aineiasz", "Hektór"], correctIndex: 0, explanation: "Odüsszeusz és Pénelopé fia Télemakhosz, aki apja keresésére indul. Patroklosz és Hektór az Iliász szereplői." },
  { id: "g09-hungarian-022", grade: 9, subject: "hungarian", tier: 1, prompt: "Mit lopott el Prométheusz az istenektől az emberek számára?", options: ["a villámot", "az ambróziát", "a tüzet", "az aranygyapjút"], correctIndex: 2, explanation: "Prométheusz a tüzet lopta el az istenektől, és az embereknek adta; ezért Zeusz a Kaukázus egyik sziklájához láncoltatta." },
  { id: "g09-hungarian-023", grade: 9, subject: "hungarian", tier: 1, prompt: "Melyik műnembe tartozik a párbeszédes, színpadra szánt mű?", options: ["publicisztika", "líra", "dráma", "epika"], correctIndex: 2, explanation: "A dráma párbeszédes formában íródik, előadásra szánják, középpontjában konfliktus áll. A líra érzelmeket fejez ki, az epika elbeszél." },
  { id: "g09-hungarian-024", grade: 9, subject: "hungarian", tier: 1, prompt: "Milyen műfajúak Aiszóposz tanító célú állatmeséi?", options: ["balladák", "eposzok", "ódák", "fabulák"], correctIndex: 3, explanation: "Aiszóposz állatmeséket, azaz fabulákat írt; a tücsök és a hangya története is ilyen. A hagyomány a „mesék Homéroszának” is nevezi." },
  { id: "g09-hungarian-025", grade: 9, subject: "hungarian", tier: 1, prompt: "Ki írta az Aeneis című eposzt?", options: ["Homérosz", "Vergilius", "Horatius", "Ovidius"], correctIndex: 1, explanation: "Az Aeneist Publius Vergilius Maro írta Augustus korában. Horatius ódáiról, Homérosz a görög eposzokról ismert." },
  { id: "g09-hungarian-026", grade: 9, subject: "hungarian", tier: 1, prompt: "Hogyan nevezzük az ellentétes jelentésű szavakat (pl. hideg – meleg)?", options: ["antonimák", "homonimák", "szinonimák", "rokon értelmű szavak"], correctIndex: 0, explanation: "Az ellentétes jelentésű szópárok az antonimák, például hideg – meleg. A szinonimák és a rokon értelmű szavak hasonló jelentésűek." },
  { id: "g09-hungarian-027", grade: 9, subject: "hungarian", tier: 1, prompt: "Hogyan nevezzük a hasonló jelentésű szavakat (pl. fut – szalad)?", options: ["homonimák", "hangutánzó szavak", "antonimák", "szinonimák"], correctIndex: 3, explanation: "A hasonló jelentésű, eltérő hangalakú szavak a szinonimák (rokon értelmű szavak), például fut – szalad. Az antonimák ellentétes jelentésűek." },
  { id: "g09-hungarian-028", grade: 9, subject: "hungarian", tier: 1, prompt: "Melyik kommunikációs tényező fogadja és értelmezi az üzenetet?", options: ["csatorna", "vevő", "zaj", "kód"], correctIndex: 1, explanation: "A vevő az, aki a közleményt fogadja és értelmezi. A csatorna a közleményt továbbító közeg, a zaj az üzenetet torzító zavar." },
  { id: "g09-hungarian-029", grade: 9, subject: "hungarian", tier: 1, prompt: "Melyik nagy nyelvcsalád tagja a magyar?", options: ["uráli", "szláv", "török", "indoeurópai"], correctIndex: 0, explanation: "A magyar az uráli nyelvcsalád finnugor főágának ugor ágába tartozik. A szláv nyelvek az indoeurópai családhoz tartoznak." },
  { id: "g09-hungarian-030", grade: 9, subject: "hungarian", tier: 1, prompt: "Ki Trója királya az Iliászban?", options: ["Odüsszeusz", "Menelaosz", "Priamosz", "Agamemnón"], correctIndex: 2, explanation: "Trója öreg királya Priamosz, Hektór apja, aki fia holttestéért könyörög Akhilleusznál. Agamemnón a görögök fővezére." },
  { id: "g09-hungarian-031", grade: 9, subject: "hungarian", tier: 1, prompt: "Milyen lény Polüphémosz, akit Odüsszeusz megvakít?", options: ["szirén", "kentaur", "nimfa", "küklopsz"], correctIndex: 3, explanation: "Polüphémosz egyszemű óriás, küklopsz, akinek a szemét Odüsszeusz vakítja meg, hogy társaival kiszabadulhasson a barlangból." },
  { id: "g09-hungarian-032", grade: 9, subject: "hungarian", tier: 2, prompt: "Ki öli meg Patrokloszt, Akhilleusz barátját az Iliászban?", options: ["Parisz", "Priamosz", "Hektór", "Agamemnón"], correctIndex: 2, explanation: "Patrokloszt Hektór győzi le, ezért Akhilleusz bosszúból visszatér a harcba, és megöli Hektórt. Priamosz Hektór apja." },
  { id: "g09-hungarian-033", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik varázslónő változtatja disznóvá Odüsszeusz társait?", options: ["Kirké", "Pénelopé", "Nauszikaá", "Kalüpszó"], correctIndex: 0, explanation: "Kirké varázslónő disznóvá változtatja Odüsszeusz társait. Kalüpszó nimfa a szigetén tartja fogva a hőst, Pénelopé a felesége." },
  { id: "g09-hungarian-034", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik nimfa tartja fogva szigetén hosszú ideig Odüsszeuszt?", options: ["Eurükleia", "Athéné", "Kirké", "Kalüpszó"], correctIndex: 3, explanation: "Kalüpszó nimfa egy eldugott szigeten tartja fogva Odüsszeuszt. Eurükleia az öreg dajka, aki hazatérésekor felismeri." },
  { id: "g09-hungarian-035", grade: 9, subject: "hungarian", tier: 2, prompt: "Ki Antigoné húga, aki fél szembeszállni a király akaratával?", options: ["Iokaszté", "Iszméné", "Eurüdiké", "Élektra"], correctIndex: 1, explanation: "Iszméné Antigoné húga; fél a király tilalmától, ezért nem segít a temetésben. Eurüdiké Kreón felesége." },
  { id: "g09-hungarian-036", grade: 9, subject: "hungarian", tier: 2, prompt: "Ki Kreón fia, Antigoné vőlegénye a drámában?", options: ["Polüneikész", "Oidipusz", "Haimón", "Teiresziasz"], correctIndex: 2, explanation: "Haimón Kreón fia és Antigoné vőlegénye. Polüneikész Antigoné bátyja, Teiresziasz a vak jós." },
  { id: "g09-hungarian-037", grade: 9, subject: "hungarian", tier: 2, prompt: "Ki a vak jós, aki figyelmezteti Kreónt az Antigonéban?", options: ["Haimón", "Kalkhász", "Prométheusz", "Teiresziasz"], correctIndex: 3, explanation: "Teiresziasz a vak jós, aki megjósolja Kreónnak, hogy ha nem vonja vissza parancsát, az több ember halálához vezet." },
  { id: "g09-hungarian-038", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik versláb áll egy rövid és egy hosszú szótagból (U –)?", options: ["jambus", "trochaeus", "spondeus", "daktilus"], correctIndex: 0, explanation: "A jambus rövid–hosszú (U –) szótagokból áll. A trochaeus ennek fordítottja (– U), a spondeus két hosszú szótag." },
  { id: "g09-hungarian-039", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik versláb áll egy hosszú és egy rövid szótagból (– U)?", options: ["anapesztus", "trochaeus", "jambus", "daktilus"], correctIndex: 1, explanation: "A trochaeus (trocheus) hosszú–rövid (– U) versláb. A jambus rövid–hosszú, az anapesztus két rövid és egy hosszú szótag." },
  { id: "g09-hungarian-040", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik kódexben maradt fenn a Halotti beszéd és könyörgés?", options: ["a Leuveni kódexben", "a Jókai-kódexben", "a Bécsi kódexben", "a Pray-kódexben"], correctIndex: 3, explanation: "A Halotti beszéd a Pray-kódex 136. lapján maradt fenn, ma az Országos Széchényi Könyvtár őrzi. A Leuveni kódexben az Ómagyar Mária-siralom olvasható." },
  { id: "g09-hungarian-041", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik római költő ódájából ered a „carpe diem” szállóige?", options: ["Catullus", "Vergilius", "Horatius", "Ovidius"], correctIndex: 2, explanation: "A „carpe diem” Horatius Leukonoéhoz írt ódájának (Carmina I. 11.) zárásából való; jelentése nagyjából: élj a mának, becsüld a jelent." },
  { id: "g09-hungarian-042", grade: 9, subject: "hungarian", tier: 2, prompt: "Ki a görög sereg fővezére az Iliászban?", options: ["Akhilleusz", "Agamemnón", "Priamosz", "Hektór"], correctIndex: 1, explanation: "A görögök fővezére Agamemnón, Mükéné királya; vele vész össze Akhilleusz az eposz elején. Priamosz és Hektór trójaiak." },
  { id: "g09-hungarian-043", grade: 9, subject: "hungarian", tier: 2, prompt: "Melyik égő városból menekül el Aeneas az Aeneis elején?", options: ["Trójából", "Rómából", "Athénból", "Karthágóból"], correctIndex: 0, explanation: "Aeneas az égő Trójából menekül el, és hosszú bolyongás után Itáliába jut. Karthágóban Dido királynőnél vendégeskedik." },
  { id: "g09-hungarian-044", grade: 9, subject: "hungarian", tier: 2, prompt: "Mi a neve az azonos alakú, de egymással rokontalan jelentésű szavaknak?", options: ["antonimák", "többjelentésű szavak", "homonimák", "szinonimák"], correctIndex: 2, explanation: "A homonimák alakja azonos, jelentésük véletlenül esik egybe, például az ír (ige) és az ír (népnév). A többjelentésű szavak jelentései rokonok." },
  { id: "g09-hungarian-045", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik versláb áll egy hosszú és két rövid szótagból (– U U)?", options: ["daktilus", "jambus", "spondeus", "anapesztus"], correctIndex: 0, explanation: "A daktilus egy hosszú és két rövid szótagból áll (– U U). Az anapesztus fordított: két rövid és egy hosszú (U U –)." },
  { id: "g09-hungarian-046", grade: 9, subject: "hungarian", tier: 3, prompt: "Hány verslábból áll a hexameter?", options: ["nyolc", "négy", "öt", "hat"], correctIndex: 3, explanation: "A hexameter hat verslábból álló sor: daktilusokból és spondeusokból, az utolsó előtti láb rendszerint daktilus. Ebben írták az Iliászt is." },
  { id: "g09-hungarian-047", grade: 9, subject: "hungarian", tier: 3, prompt: "Egy hexameter és milyen sor alkot együtt disztichont?", options: ["egy rímes felező tizenkettes", "egy pentameter", "egy jambikus sor", "egy újabb hexameter"], correctIndex: 1, explanation: "A disztichon egy hexameterből és egy pentameterből álló, rímtelen sorpár. A pentameter főleg a disztichon második soraként fordul elő." },
  { id: "g09-hungarian-048", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyek a magyar nyelv legközelebbi rokon nyelvei?", options: ["a finn és az észt", "a nyenyec és a szölkup", "a manysi és a hanti", "a török és a mongol"], correctIndex: 2, explanation: "A magyar legközelebbi rokonai az obi-ugor nyelvek: a manysi (vogul) és a hanti (osztják). A finn és az észt távolabbi, finn-permi rokon." },
  { id: "g09-hungarian-049", grade: 9, subject: "hungarian", tier: 3, prompt: "A „vár” ige és a „vár” főnév jelentése nem függ össze. Mi ez a jelenség?", options: ["antonímia", "poliszémia", "homonímia", "szinonímia"], correctIndex: 2, explanation: "A vár (várakozik) és a vár (erősség) jelentése független, csak alakjuk azonos: ez a homonímia (azonos alakúság). Poliszémia akkor van, ha a jelentések összefüggnek." },
  { id: "g09-hungarian-050", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik kódexben maradt fenn az Ómagyar Mária-siralom?", options: ["a Leuveni kódexben", "a Pray-kódexben", "a Bécsi kódexben", "a Müncheni kódexben"], correctIndex: 0, explanation: "Az Ómagyar Mária-siralom a Leuveni kódex egyik lapján maradt fenn. A Pray-kódex a Halotti beszédet őrizte meg." },
  { id: "g09-hungarian-051", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik évben került elő az Ómagyar Mária-siralom?", options: ["1956-ban", "1840-ben", "1770-ben", "1922-ben"], correctIndex: 3, explanation: "A kódexet 1922-ben találták meg, a Leuveni Egyetem által egy müncheni könyvkereskedésben vásárolt anyagban; maga a szöveg a 13. századból való." },
  { id: "g09-hungarian-052", grade: 9, subject: "hungarian", tier: 3, prompt: "Mikor keletkezett a Halotti beszéd és könyörgés?", options: ["1301 után", "1192 és 1195 között", "1000 körül", "1456-ban"], correctIndex: 1, explanation: "A Halotti beszéd 1192 és 1195 között, III. Béla uralkodásának végén keletkezett, valószínűleg a boldvai bencés monostorban." },
  { id: "g09-hungarian-053", grade: 9, subject: "hungarian", tier: 3, prompt: "Mi a Balassi-strófa rímképlete?", options: ["aab ccb ddb", "abba cddc", "aabb ccdd", "abab cdcd"], correctIndex: 0, explanation: "A Balassi-strófa rímképlete aab ccb ddb: a páros a, c és d rímek mellett a b rím az egész versszakon végighúzódik." },
  { id: "g09-hungarian-054", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik valós személyt nevezi Balassi verseiben Júliának?", options: ["Zrínyi Ilonát", "Szilágyi Erzsébetet", "Dobó Krisztinát", "Losonczy Annát"], correctIndex: 3, explanation: "A Júlia-versek ihletője Losonczy Anna volt, akit Balassi a verseiben Júliának nevezett el." },
  { id: "g09-hungarian-055", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik vár ostrománál sebesült meg halálosan Balassi 1594-ben?", options: ["Szigetvár", "Kőszeg", "Esztergom", "Eger"], correctIndex: 2, explanation: "Balassi Bálint 1594. május 19-én Esztergom ostrománál sebesült meg, és május 30-án a táborban meghalt. Eger és Szigetvár ostroma más évekhez kötődik." },
  { id: "g09-hungarian-056", grade: 9, subject: "hungarian", tier: 3, prompt: "Melyik karthágói királynő szeret bele Aeneasba?", options: ["Lavinia", "Dido", "Kleopátra", "Kirké"], correctIndex: 1, explanation: "Karthágó alapítója, Dido királynő beleszeret Aeneasba, de nem tudja maradásra bírni; a hős továbbhajózik Itália felé." },
  { id: "g09-hungarian-057", grade: 9, subject: "hungarian", tier: 3, prompt: "Arisztotelész szerint ki vezette be a harmadik színészt a tragédiába?", options: ["Euripidész", "Arisztophanész", "Aiszkhülosz", "Szophoklész"], correctIndex: 3, explanation: "Arisztotelész Poétikája szerint Szophoklész alkalmazott először három színészt és díszletet. A kar 15 főre bővítését nem Arisztotelész, hanem az ókori életrajza tulajdonítja neki." },
  // science
  { id: "g09-science-001", grade: 9, subject: "science", tier: 1, prompt: "Mekkora a szabadon eső test gyorsulása a Föld felszínén iskolai kerekítéssel?", options: ["10 m/s²", "1 m/s²", "100 m/s²", "0,1 m/s²"], correctIndex: 0, explanation: "A nehézségi gyorsulás értéke g ≈ 9,81 m/s², ezt iskolai számolásnál 10 m/s²-re kerekítjük. Ennyivel nő a szabadon eső test sebessége másodpercenként." },
  { id: "g09-science-002", grade: 9, subject: "science", tier: 1, prompt: "Melyik részecske töltése negatív az atomban?", options: ["proton", "neutron", "elektron", "atommag"], correctIndex: 2, explanation: "Az elektron negatív töltésű, az atommag körül található. A proton pozitív, a neutron semleges, ezért az atommag összességében pozitív." },
  { id: "g09-science-003", grade: 9, subject: "science", tier: 1, prompt: "Melyik sejtalkotóban zajlik a sejtlégzés, amely energiát szabadít fel?", options: ["sejtmag", "sejthártya", "zöld színtest", "mitokondrium"], correctIndex: 3, explanation: "A mitokondrium a sejt energiaközpontja: itt zajlik a sejtlégzés, amely a tápanyagok lebontásával energiát szabadít fel." },
  { id: "g09-science-004", grade: 9, subject: "science", tier: 1, prompt: "Mi határozza meg, hogy egy atom melyik kémiai elemhez tartozik?", options: ["a neutronok száma", "a protonok száma", "a tömegszám", "az elektronhéjak száma"], correctIndex: 1, explanation: "Az elemet a protonok száma, azaz a rendszám határozza meg. Például minden 6 protonos atom szén, a neutronok száma eltérhet (izotópok)." },
  { id: "g09-science-005", grade: 9, subject: "science", tier: 1, prompt: "Melyik a Föld legkülső szilárd gömbhéja?", options: ["földkéreg", "külső mag", "köpeny", "belső mag"], correctIndex: 0, explanation: "A Föld belső szerkezete kívülről befelé: földkéreg, köpeny, külső mag és belső mag. A legkülső, legvékonyabb réteg a földkéreg." },
  { id: "g09-science-006", grade: 9, subject: "science", tier: 1, prompt: "Melyik a légkör legalsó rétege, ahol az időjárási jelenségek zajlanak?", options: ["sztratoszféra", "mezoszféra", "termoszféra", "troposzféra"], correctIndex: 3, explanation: "A légkör legalsó rétege a troposzféra: itt van a levegő és a vízgőz nagy része, ezért itt alakulnak ki a felhők és a csapadék." },
  { id: "g09-science-007", grade: 9, subject: "science", tier: 2, prompt: "Egy 2 kg tömegű testre 10 N eredő erő hat. Mekkora a gyorsulása?", options: ["20 m/s²", "5 m/s²", "0,2 m/s²", "12 m/s²"], correctIndex: 1, explanation: "Newton II. törvénye szerint F = m · a, így a = F : m = 10 N : 2 kg = 5 m/s²." },
  { id: "g09-science-008", grade: 9, subject: "science", tier: 2, prompt: "Egy autó egyenletesen haladva 2 óra alatt 150 km-t tesz meg. Mekkora a sebessége?", options: ["300 km/h", "150 km/h", "75 km/h", "50 km/h"], correctIndex: 2, explanation: "Egyenletes mozgásnál a sebesség az út és az idő hányadosa: v = s : t = 150 km : 2 h = 75 km/h." },
  { id: "g09-science-009", grade: 9, subject: "science", tier: 2, prompt: "Hány neutron van a 11-es rendszámú, 23-as tömegszámú nátriumatom magjában?", options: ["11", "23", "34", "12"], correctIndex: 3, explanation: "A tömegszám a protonok és neutronok összege, a rendszám a protonok száma. Így a neutronok száma 23 − 11 = 12." },
  { id: "g09-science-010", grade: 9, subject: "science", tier: 2, prompt: "Melyik sejtalkotó hiányzik a prokarióta sejtekből?", options: ["sejthártya", "riboszóma", "sejtmag", "citoplazma"], correctIndex: 2, explanation: "A prokarióta sejteknek (pl. baktériumok) nincs maghártyával határolt sejtmagjuk, örökítőanyaguk szabadon van a citoplazmában. Sejthártyájuk és riboszómájuk van." },
  { id: "g09-science-011", grade: 9, subject: "science", tier: 2, prompt: "Melyik törvény mondja ki, hogy minden erőhatással szemben vele egyenlő nagyságú, ellentétes irányú ellenerő lép fel?", options: ["Newton III. törvénye", "Newton I. törvénye", "Newton II. törvénye", "az energiamegmaradás törvénye"], correctIndex: 0, explanation: "Newton III. törvénye a hatás-ellenhatás törvénye: ha egy test erőt fejt ki egy másikra, az is ugyanakkora, ellentétes irányú erővel hat vissza." },
  { id: "g09-science-012", grade: 9, subject: "science", tier: 2, prompt: "Milyen részecske keletkezik, ha egy nátriumatom lead egy elektront?", options: ["negatív ion", "pozitív ion", "semleges atom", "izotóp"], correctIndex: 1, explanation: "Elektron leadásakor több proton marad, mint elektron, ezért pozitív ion (kation) keletkezik: Na → Na⁺ + e⁻." },
  { id: "g09-science-013", grade: 9, subject: "science", tier: 3, prompt: "Mekkora lesz egy nyugalomból szabadon eső test sebessége 3 s után, ha g ≈ 10 m/s²?", options: ["45 m/s", "10 m/s", "90 m/s", "30 m/s"], correctIndex: 3, explanation: "Szabadesésnél v = g · t = 10 m/s² · 3 s = 30 m/s. A 45 m az ennyi idő alatt megtett út lenne (g · t² / 2), nem a sebesség." },
  { id: "g09-science-014", grade: 9, subject: "science", tier: 3, prompt: "Milyen kémiai kötés tartja össze a nátriumot és a klórt a konyhasóban?", options: ["kovalens kötés", "fémes kötés", "ionkötés", "hidrogénkötés"], correctIndex: 2, explanation: "A nátrium elektront ad át a klórnak, így Na⁺ és Cl⁻ ionok keletkeznek. Az ellentétes töltésű ionok vonzása az ionkötés." },
  { id: "g09-science-015", grade: 9, subject: "science", tier: 3, prompt: "Melyik sejtalkotóban zajlik a fotoszintézis a növényi sejtben?", options: ["mitokondrium", "zöld színtest", "sejtmag", "sejtfal"], correctIndex: 1, explanation: "A fotoszintézis a zöld színtestben zajlik: a klorofill megköti a fény energiáját, és szén-dioxidból meg vízből szőlőcukor és oxigén keletkezik." },
  { id: "g09-science-016", grade: 9, subject: "science", tier: 3, prompt: "Mi hozta létre a lemeztektonika szerint a Himalája hegységet?", options: ["két kőzetlemez távolodása", "a folyók eróziója", "a szél építő munkája", "két kontinentális lemez ütközése"], correctIndex: 3, explanation: "A Himalája két kontinentális lemez ütközésével gyűrődött fel: az Indiai-lemez az Eurázsiai-lemeznek ütközött. A lemezek távolodása óceáni hátságot hoz létre." },
  { id: "g09-science-017", grade: 9, subject: "science", tier: 3, prompt: "Egy test 5 s alatt egyenletesen gyorsulva 2 m/s-ról 12 m/s-ra gyorsul. Mekkora a gyorsulása?", options: ["2 m/s²", "2,4 m/s²", "10 m/s²", "0,5 m/s²"], correctIndex: 0, explanation: "A gyorsulás a sebességváltozás és az idő hányadosa: a = (12 − 2) m/s : 5 s = 2 m/s²." },
  { id: "g09-science-018", grade: 9, subject: "science", tier: 3, prompt: "Hány elektron van a 17-es rendszámú klóratom legkülső elektronhéján?", options: ["17", "8", "7", "1"], correctIndex: 2, explanation: "A klór 17 elektronja héjanként 2, 8, 7 eloszlású, így a legkülső héjon 7 elektron van. Ezért egy elektron felvételével éri el a nemesgáz-szerkezetet." },
  // science — JBb bővítés (2026-11-16): gyártó → validátor → vak megoldó + tantárgyi audit → javítás
  { id: "g09-science-019", grade: 9, subject: "science", tier: 1, prompt: "Mi a munka SI-mértékegysége?", options: ["joule", "pascal", "watt", "newton"], correctIndex: 0, explanation: "A munka SI-egysége a joule (J = N · m): 1 joule munkát végez az 1 N erő 1 m-es elmozdulás során. A watt a teljesítmény, a newton az erő egysége." },
  { id: "g09-science-020", grade: 9, subject: "science", tier: 1, prompt: "Mi a teljesítmény SI-mértékegysége?", options: ["joule", "volt", "watt", "newton"], correctIndex: 2, explanation: "A teljesítmény az egységnyi idő alatt végzett munka, egysége a watt: 1 W = 1 J/s. A joule a munka, a volt a feszültség egysége." },
  { id: "g09-science-021", grade: 9, subject: "science", tier: 1, prompt: "Melyik Newton-törvényt nevezik a tehetetlenség törvényének?", options: ["Newton II. törvényét", "a gravitációs törvényt", "Newton III. törvényét", "Newton I. törvényét"], correctIndex: 3, explanation: "Newton I. törvénye a tehetetlenség törvénye: erőhatás nélkül a test megtartja nyugalmát vagy egyenes vonalú egyenletes mozgását. A II. törvény az F = m · a." },
  { id: "g09-science-022", grade: 9, subject: "science", tier: 1, prompt: "Hány bolygó kering a Nap körül?", options: ["tíz", "nyolc", "kilenc", "hét"], correctIndex: 1, explanation: "A Naprendszerben nyolc bolygó van: négy kőzetbolygó (Merkúr, Vénusz, Föld, Mars) és négy óriásbolygó (Jupiter, Szaturnusz, Uránusz, Neptunusz)." },
  { id: "g09-science-023", grade: 9, subject: "science", tier: 1, prompt: "Melyik a Naprendszer legnagyobb bolygója?", options: ["Szaturnusz", "Föld", "Jupiter", "Neptunusz"], correctIndex: 2, explanation: "A legnagyobb bolygó a Jupiter, a Naptól az ötödik. A Szaturnusz a második legnagyobb, a Neptunusz a legtávolabbi bolygó." },
  { id: "g09-science-024", grade: 9, subject: "science", tier: 1, prompt: "Melyik bolygó halad a Naphoz legközelebbi pályán?", options: ["Vénusz", "Merkúr", "Föld", "Mars"], correctIndex: 1, explanation: "A Naphoz a Merkúr van a legközelebb, utána következik a Vénusz, a Föld és a Mars. A Föld a harmadik bolygó a Naptól." },
  { id: "g09-science-025", grade: 9, subject: "science", tier: 1, prompt: "Mi az anyagmennyiség SI-mértékegysége?", options: ["mól", "gramm", "liter", "kelvin"], correctIndex: 0, explanation: "Az anyagmennyiség egysége a mól; egy mólnyi anyag Avogadro-számú részecskét tartalmaz. A gramm tömeg-, a liter térfogategység." },
  { id: "g09-science-026", grade: 9, subject: "science", tier: 1, prompt: "Melyik sejtalkotóban zajlik a fehérjék szintézise?", options: ["sejthártyában", "sejtfalban", "zöld színtestben", "riboszómában"], correctIndex: 3, explanation: "A fehérjeszintézis a riboszómában zajlik: itt fordítják le az mRNS kódját aminosav-sorrendre. Riboszóma minden élőlény sejtjében van." },
  { id: "g09-science-027", grade: 9, subject: "science", tier: 1, prompt: "Melyik anyag adja a növényi sejtfal szilárdságát?", options: ["keményítő", "koleszterin", "kitin", "cellulóz"], correctIndex: 3, explanation: "A növényi sejtfal legerősebb összetevője a cellulóz nevű szénhidrát-polimer. A kitin a gombák sejtfalát alkotja." },
  { id: "g09-science-028", grade: 9, subject: "science", tier: 1, prompt: "Melyik igaz a vírusokra?", options: ["nincs sejtes felépítésük", "eukarióta sejtek", "prokarióta sejtek", "egysejtű állatok"], correctIndex: 0, explanation: "A vírusoknak nincs sejtes felépítésük: fehérjeburokból és örökítőanyagból állnak, és csak élő sejtben szaporodnak. Ezért nem prokarióták és nem eukarióták." },
  { id: "g09-science-029", grade: 9, subject: "science", tier: 1, prompt: "Melyik gáz aránya a legnagyobb a Föld légkörében?", options: ["szén-dioxid", "nitrogén", "argon", "oxigén"], correctIndex: 1, explanation: "A légkör térfogatának mintegy 78%-a nitrogén, kb. 21%-a oxigén; az argon nagyjából 0,9%, a szén-dioxid csak 0,04% körüli." },
  { id: "g09-science-030", grade: 9, subject: "science", tier: 1, prompt: "Mi segítségével mozog a papucsállatka?", options: ["ostorral", "izmokkal", "csillókkal", "állábakkal"], correctIndex: 2, explanation: "A papucsállatka csillós egysejtű: testét csillók borítják, és csillókkal, azok összehangolt mozgásával hajtja magát. Állábakkal az amőba mozog." },
  { id: "g09-science-031", grade: 9, subject: "science", tier: 1, prompt: "Hogy nevezzük az azonos protonszámú, de eltérő neutronszámú atomokat?", options: ["elektronpárok", "ionok", "molekulák", "izotópok"], correctIndex: 3, explanation: "Az izotópok atommagja azonos számú protonból, de eltérő számú neutronból áll, ezért ugyanannak az elemnek a tömegszámban eltérő változatai." },
  { id: "g09-science-032", grade: 9, subject: "science", tier: 2, prompt: "Mekkora a lendülete egy 3 m/s-mal haladó, 2 kg-os testnek?", options: ["9 kg · m/s", "5 kg · m/s", "6 kg · m/s", "1,5 kg · m/s"], correctIndex: 2, explanation: "A lendület p = m · v = 2 kg · 3 m/s = 6 kg · m/s. Az 1,5 a hányados, az 5 az összeg, a 9 a ½ · m · v² számértéke lenne." },
  { id: "g09-science-033", grade: 9, subject: "science", tier: 2, prompt: "Mekkora munkát végez az 50 N erő 4 m úton, ha az erő az út irányába mutat?", options: ["200 J", "12,5 J", "46 J", "54 J"], correctIndex: 0, explanation: "Ha az erő és az elmozdulás egyirányú, W = F · s = 50 N · 4 m = 200 J. A 12,5 J a hibás osztás, az 54 J az összeadás eredménye." },
  { id: "g09-science-034", grade: 9, subject: "science", tier: 2, prompt: "Mekkora a teljesítmény, ha egy gép 20 s alatt 600 J munkát végez?", options: ["12 000 W", "580 W", "3 W", "30 W"], correctIndex: 3, explanation: "P = W / t = 600 J / 20 s = 30 W. A 12 000 W a munka és az idő szorzata, az 580 W a különbségük — egyik sem teljesítmény." },
  { id: "g09-science-035", grade: 9, subject: "science", tier: 2, prompt: "A légkör melyik rétegében található az ózonréteg?", options: ["termoszférában", "sztratoszférában", "mezoszférában", "troposzférában"], correctIndex: 1, explanation: "Az ózonréteg a sztratoszférában, kb. 20–25 km magasan van, és elnyeli a Nap ultraibolya sugárzásának nagy részét." },
  { id: "g09-science-036", grade: 9, subject: "science", tier: 2, prompt: "Milyen halmazállapotú a Föld külső magja?", options: ["légnemű", "plazma", "folyékony", "szilárd"], correctIndex: 2, explanation: "A külső mag folyékony vas-nikkel réteg, áramlása hozza létre a Föld mágneses terét. A belső mag ezzel szemben szilárd." },
  { id: "g09-science-037", grade: 9, subject: "science", tier: 2, prompt: "Melyik kőzetből jön létre átalakulással a márvány?", options: ["gránitból", "mészkőből", "bazaltból", "homokkőből"], correctIndex: 1, explanation: "A márvány átalakult (metamorf) kőzet: tömör mészkőből jön létre átkristályosodással, ezért főként kalcitból áll." },
  { id: "g09-science-038", grade: 9, subject: "science", tier: 2, prompt: "Hány elektron van a nemesgázok (a hélium kivételével) külső héján?", options: ["8", "1", "4", "2"], correctIndex: 0, explanation: "A nemesgázok külső héján 8 elektron, elektronoktett van; ez a nemesgáz-szerkezet rendkívül stabil, ezért alig reagálnak. A héliumnak 2 elektronja van." },
  { id: "g09-science-039", grade: 9, subject: "science", tier: 2, prompt: "Hány neutron van a deutérium (²H) atommagjában?", options: ["2", "0", "3", "1"], correctIndex: 3, explanation: "A deutérium tömegszáma 2, rendszáma 1, így neutronszáma 2 − 1 = 1. A prócium magjában 0, a tríciuméban 2 neutron van." },
  { id: "g09-science-040", grade: 9, subject: "science", tier: 2, prompt: "Legfeljebb hány elektron lehet az atom első elektronhéján?", options: ["8", "1", "2", "18"], correctIndex: 2, explanation: "Egy héjon legfeljebb 2n² elektron lehet; az első héjon (n = 1) ez 2 · 1² = 2. A második héjon 8, a harmadikon 18 elektron fér el." },
  { id: "g09-science-041", grade: 9, subject: "science", tier: 2, prompt: "Milyen kötés kapcsolja össze a hidrogénmolekula (H₂) két atomját?", options: ["hidrogénkötés", "kovalens kötés", "ionkötés", "fémes kötés"], correctIndex: 1, explanation: "A két hidrogénatom közös elektronpárt alkot (H–H), ez kovalens kötés. Ionkötés fém és nemfém között, például a konyhasóban jön létre." },
  { id: "g09-science-042", grade: 9, subject: "science", tier: 2, prompt: "Milyen anyag alkotja a gombák sejtfalát?", options: ["kitin", "keratin", "keményítő", "cellulóz"], correctIndex: 0, explanation: "A gombák sejtfalát kitin alkotja, a növényekét cellulóz. Az állati sejteknek nincs sejtfaluk." },
  { id: "g09-science-043", grade: 9, subject: "science", tier: 2, prompt: "Mi alkotja a sejthártya alapvázát?", options: ["cellulózrostok", "keményítőszemcsék", "kitinlemezek", "foszfolipid kettős réteg"], correctIndex: 3, explanation: "A sejthártya alapja egy foszfolipid kettős réteg, amelybe fehérjék ágyazódnak; ez határolja el a sejtet és szabályozza az anyagforgalmat." },
  { id: "g09-science-044", grade: 9, subject: "science", tier: 2, prompt: "Melyik szélességi kör felett delel merőlegesen a Nap június 21. körül?", options: ["a Baktérítő", "a Ráktérítő", "az északi sarkkör", "az Egyenlítő"], correctIndex: 1, explanation: "A nyári napfordulókor a delelő Nap sugarai a Ráktérítőn (kb. 23,4° északi szélesség) esnek merőlegesen a felszínre." },
  { id: "g09-science-045", grade: 9, subject: "science", tier: 3, prompt: "Mekkora utat tesz meg 4 s alatt a nyugalomból 2 m/s²-tel gyorsuló test?", options: ["32 m", "8 m", "4 m", "16 m"], correctIndex: 3, explanation: "Nyugalomból indulva s = (a/2) · t² = 1 · 16 = 16 m. A 32 m a feles szorzó elhagyásával, a 8 m az a · t szorzatból adódna." },
  { id: "g09-science-046", grade: 9, subject: "science", tier: 3, prompt: "Mekkora a helyzeti energiája egy 2 kg-os testnek 5 m magasan (g ≈ 10 m/s²)?", options: ["100 J", "20 J", "10 J", "50 J"], correctIndex: 0, explanation: "A helyzeti energia E = m · g · h = 2 kg · 10 m/s² · 5 m = 100 J. A 10 J az m · h, az 50 J a g · h szorzat lenne." },
  { id: "g09-science-047", grade: 9, subject: "science", tier: 3, prompt: "Mekkora a mozgási energiája egy 4 m/s-mal haladó, 2 kg-os testnek?", options: ["4 J", "16 J", "8 J", "32 J"], correctIndex: 1, explanation: "A mozgási energia ½ · m · v² = ½ · 2 kg · (4 m/s)² = 16 J. A 32 J a feles szorzó elhagyásából, a 8 J a lendület számértékéből jön." },
  { id: "g09-science-048", grade: 9, subject: "science", tier: 3, prompt: "Hány métert esik 2 s alatt a nyugalomból szabadon eső test (g ≈ 10 m/s²)?", options: ["5 m", "40 m", "20 m", "10 m"], correctIndex: 2, explanation: "A szabadon eső test útja s = (g/2) · t² = 5 · 4 = 20 m. A 40 m a feles szorzó elhagyásából, a 10 m a g · t / 2 hibás képletből jön." },
  { id: "g09-science-049", grade: 9, subject: "science", tier: 3, prompt: "Körülbelül hány részecskét tartalmaz 1 mól anyag?", options: ["12", "6 · 10²³", "3 · 10⁸", "1,6 · 10⁻¹⁹"], correctIndex: 1, explanation: "Egy mól anyagban Avogadro-számnyi, kerekítve 6 · 10²³ részecske van. A 3 · 10⁸ a fénysebesség (m/s), a 12 a szén-12 tömegszáma." },
  { id: "g09-science-050", grade: 9, subject: "science", tier: 3, prompt: "Mi okozza a fémek jó elektromos vezetését?", options: ["az ionkötések", "a neutronok mozgása", "a szabadon mozgó elektronok", "a protonok vándorlása"], correctIndex: 2, explanation: "A fémes kötésben a vegyértékelektronok delokalizáltak, szabadon mozgó elektronokként könnyen elmozdulnak, ezért feszültség hatására áram folyik." },
  { id: "g09-science-051", grade: 9, subject: "science", tier: 3, prompt: "Hol keletkezik új óceáni kéreg a lemeztektonika szerint?", options: ["a mélytengeri árkoknál", "a hegységek csúcsán", "a kontinensek belsejében", "az óceánközépi hátságoknál"], correctIndex: 3, explanation: "Az óceánközépi hátságoknál a lemezek távolodnak egymástól, a feláramló magmából új óceáni kéreg képződik. A mélytengeri árkoknál a lemez alábukik." },
  { id: "g09-science-052", grade: 9, subject: "science", tier: 3, prompt: "Ki fogalmazta meg elsőként a kontinensvándorlás elméletét?", options: ["Alfred Wegener", "Isaac Newton", "Nikolausz Kopernikusz", "Charles Darwin"], correctIndex: 0, explanation: "A kontinensvándorlást Alfred Wegener fogalmazta meg összefüggő elméletként az 1910-es években; ebből fejlődött ki később a lemeztektonika." },
  { id: "g09-science-053", grade: 9, subject: "science", tier: 3, prompt: "Miből épül fel a vírusok örökítőanyagát körülvevő kapszid?", options: ["cellulózból", "keményítőből", "kitinből", "fehérjéből"], correctIndex: 3, explanation: "A virion nukleinsavból (DNS vagy RNS) és az azt körülvevő, fehérjéből álló burokból, a kapszidból épül fel; egyes vírusoknak külső lipidburka is van." },
  { id: "g09-science-054", grade: 9, subject: "science", tier: 3, prompt: "Mi a papucsállatka összehúzódó üregecskéjének feladata?", options: ["a vízháztartás szabályozása", "a táplálék megemésztése", "a sejt mozgatása", "a fotoszintézis"], correctIndex: 0, explanation: "Az édesvízi papucsállatkába folyamatosan víz áramlik; az összehúzódó üregecskék ozmotikus szabályozással, a vízháztartás szabályozásával távolítják el a felesleget." },
  { id: "g09-science-055", grade: 9, subject: "science", tier: 3, prompt: "Melyik gömbhéj adja a Föld térfogatának legnagyobb részét?", options: ["a földkéreg", "a belső mag", "a köpeny", "a külső mag"], correctIndex: 2, explanation: "A köpeny mintegy 2900 km vastag, a Föld térfogatának kb. 84%-át adja. A földkéreg a térfogatnak csak kb. 1%-a." },
  { id: "g09-science-056", grade: 9, subject: "science", tier: 3, prompt: "Melyik elem a Föld magjának fő alkotója?", options: ["szilícium", "vas", "alumínium", "oxigén"], correctIndex: 1, explanation: "A Föld magja főként vasból áll, kisebb mennyiségű nikkellel. A szilícium és az oxigén a kéreg és a köpeny kőzeteinek fő elemei." },
  { id: "g09-science-057", grade: 9, subject: "science", tier: 3, prompt: "Hány elektron van a 8-as rendszámú oxigénatom második héján?", options: ["6", "4", "2", "8"], correctIndex: 0, explanation: "Az oxigénatomnak 8 elektronja van; az első héjon legfeljebb 2 fér el, így a második héjra 8 − 2 = 6 elektron jut." },
  // history
  { id: "g09-history-001", grade: 9, subject: "history", tier: 1, prompt: "Melyik folyó mentén alakult ki az ókori egyiptomi civilizáció?", options: ["Tigris", "Eufrátesz", "Indus", "Nílus"], correctIndex: 3, explanation: "Az ókori Egyiptom a Nílus mentén alakult ki. A folyó évenkénti áradása termékeny iszapot hagyott maga után, ez tette lehetővé a földművelést." },
  { id: "g09-history-002", grade: 9, subject: "history", tier: 1, prompt: "Mikor zajlott a marathóni csata?", options: ["Kr. e. 490", "Kr. e. 776", "Kr. e. 44", "Kr. u. 476"], correctIndex: 0, explanation: "A marathóni csatában Kr. e. 490-ben az athéniak legyőzték a perzsa sereget. Ez a görög–perzsa háborúk egyik leghíresebb ütközete." },
  { id: "g09-history-003", grade: 9, subject: "history", tier: 1, prompt: "Melyik két folyó között terült el Mezopotámia?", options: ["Nílus és Jordán", "Indus és Gangesz", "Tigris és Eufrátesz", "Sárga-folyó és Jangce"], correctIndex: 2, explanation: "Mezopotámia neve folyóközt jelent: a Tigris és Eufrátesz között terült el. Itt alakultak ki a sumer városállamok és Babilon." },
  { id: "g09-history-004", grade: 9, subject: "history", tier: 1, prompt: "Melyik évben bukott meg a Nyugatrómai Birodalom?", options: ["Kr. u. 395", "Kr. u. 476", "Kr. u. 800", "Kr. u. 1453"], correctIndex: 1, explanation: "A Nyugatrómai Birodalom Kr. u. 476-ban bukott meg, amikor Odoaker germán vezér letette az utolsó nyugatrómai császárt. Ezt tekintjük az ókor végének." },
  { id: "g09-history-005", grade: 9, subject: "history", tier: 1, prompt: "Kit koronázott császárrá a pápa Rómában 800 karácsonyán?", options: ["Nagy Károly", "Justinianus", "Augustus", "Nagy Sándor"], correctIndex: 0, explanation: "800 karácsonyán III. Leó pápa Nagy Károly frank uralkodót koronázta császárrá, ezzel felújította a nyugati császári címet." },
  { id: "g09-history-006", grade: 9, subject: "history", tier: 1, prompt: "Melyik görög városállamban alakult ki a demokrácia?", options: ["Athén", "Spárta", "Korinthosz", "Théba"], correctIndex: 0, explanation: "A demokrácia Athénban alakult ki a Kr. e. 6–5. században. Spárta ezzel szemben katonai jellegű, kevesek uralmán alapuló állam volt." },
  { id: "g09-history-007", grade: 9, subject: "history", tier: 2, prompt: "Kinek a Kr. e. 508 körüli reformjai vezették be Athénban a cserépszavazást?", options: ["Periklész", "Szolón", "Kleiszthenész", "Drakón"], correctIndex: 2, explanation: "Kleiszthenész reformjai teremtették meg az athéni demokrácia alapjait, köztük a cserépszavazást (osztrakiszmosz), amellyel a zsarnokságra törőket száműzhették." },
  { id: "g09-history-008", grade: 9, subject: "history", tier: 2, prompt: "Melyik makedón uralkodó hódította meg a Perzsa Birodalmat, és jutott el seregével Indiáig?", options: ["II. Philipposz", "Nagy Sándor", "Dareiosz", "Xerxész"], correctIndex: 1, explanation: "Nagy Sándor Kr. e. 334-től hadjárataival meghódította a Perzsa Birodalmat, és egészen Indiáig jutott. Apja, II. Philipposz egyesítette a görögséget." },
  { id: "g09-history-009", grade: 9, subject: "history", tier: 2, prompt: "Melyik évben jött létre a hagyomány szerint a Római Köztársaság az utolsó király elűzése után?", options: ["Kr. e. 753", "Kr. e. 44", "Kr. e. 27", "Kr. e. 509"], correctIndex: 3, explanation: "A hagyomány szerint Kr. e. 509-ben űzték el az utolsó etruszk királyt, és ekkor jött létre a Római Köztársaság. A Kr. e. 753 Róma alapításának éve." },
  { id: "g09-history-010", grade: 9, subject: "history", tier: 2, prompt: "Melyik két hatalom vívta egymással a pun háborúkat?", options: ["Róma és Karthágó", "Athén és Spárta", "Róma és Perzsia", "Egyiptom és Asszíria"], correctIndex: 0, explanation: "A pun háborúkat Róma és Karthágó vívta a Földközi-tenger nyugati részének uralmáért. A harmadik háború végén, Kr. e. 146-ban Róma elpusztította Karthágót." },
  { id: "g09-history-011", grade: 9, subject: "history", tier: 2, prompt: "Mikor gyilkolták meg Julius Caesart?", options: ["Kr. e. 490", "Kr. e. 509", "Kr. e. 27", "Kr. e. 44"], correctIndex: 3, explanation: "Julius Caesart Kr. e. 44-ben, március idusán szenátori összeesküvők gyilkolták meg, mert egyeduralmától féltették a köztársaságot." },
  { id: "g09-history-012", grade: 9, subject: "history", tier: 2, prompt: "Melyik bizánci császár gyűjttette össze a római jogot a Corpus Iuris Civilisben?", options: ["Constantinus", "Nagy Károly", "Justinianus", "Augustus"], correctIndex: 2, explanation: "Justinianus bizánci császár (527–565) rendelte el a római jog összegyűjtését. A Corpus Iuris Civilis az európai jogfejlődés egyik alapja lett." },
  { id: "g09-history-013", grade: 9, subject: "history", tier: 3, prompt: "Ki volt az első római császár, aki Kr. e. 27-től kiépítette a principatust?", options: ["Julius Caesar", "Augustus", "Nero", "Constantinus"], correctIndex: 1, explanation: "Octavianus Kr. e. 27-ben kapta az Augustus nevet, és kiépítette a principatust: a köztársasági formák mögött egyeduralmat. Őt tekintjük az első római császárnak." },
  { id: "g09-history-014", grade: 9, subject: "history", tier: 3, prompt: "Melyik athéni államférfi vezetése alatt élte fénykorát az athéni demokrácia a Kr. e. 5. század közepén?", options: ["Kleiszthenész", "Szolón", "Drakón", "Periklész"], correctIndex: 3, explanation: "Periklész idején, a Kr. e. 5. század közepén élte fénykorát az athéni demokrácia. Ekkor épült újjá az Akropolisz, és bevezették a napidíjat." },
  { id: "g09-history-015", grade: 9, subject: "history", tier: 3, prompt: "Melyik római császár biztosította 313-ban a milánói ediktummal a keresztények szabad vallásgyakorlását?", options: ["Nero", "Theodosius", "Diocletianus", "Constantinus"], correctIndex: 3, explanation: "Constantinus császár 313-ban a milánói ediktummal engedélyezte a keresztény vallás szabad gyakorlását. Theodosius később, 380-ban tette államvallássá." },
  { id: "g09-history-016", grade: 9, subject: "history", tier: 3, prompt: "Melyik nép megjelenése indította el 375 körül a népvándorlás nagy hullámát Európában?", options: ["a frankok", "a vandálok", "a hunok", "a longobárdok"], correctIndex: 2, explanation: "A hunok 375 körül átkeltek a Donon, és megtámadták a keleti gótokat. Ez indította el a germán népek tömeges vándorlását a Római Birodalom felé." },
  { id: "g09-history-017", grade: 9, subject: "history", tier: 3, prompt: "Melyik évben vált ketté véglegesen a Római Birodalom keleti és nyugati részre?", options: ["Kr. u. 313", "Kr. u. 476", "Kr. u. 395", "Kr. u. 800"], correctIndex: 2, explanation: "Theodosius császár halála után, Kr. u. 395-ben a birodalom véglegesen kettévált. A keleti rész Bizánc néven még közel ezer évig fennmaradt." },
  { id: "g09-history-018", grade: 9, subject: "history", tier: 3, prompt: "Melyik uralkodó egyesítette először Kínát Kr. e. 221-ben, és lett az első kínai császár?", options: ["Hammurapi", "Csin Si Huang-ti", "Buddha", "Asóka"], correctIndex: 1, explanation: "Csin Si Huang-ti Kr. e. 221-ben egyesítette Kínát és felvette a császári címet. Hammurapi babiloni király, Asóka indiai uralkodó volt." },
  // history — JBb bővítés (2026-11-16): gyártó → validátor → vak megoldó + tantárgyi audit → javítás
  { id: "g09-history-019", grade: 9, subject: "history", tier: 1, prompt: "Melyik birodalom királya volt Hammurapi?", options: ["az Óbabiloni Birodalom", "az Óperzsa Birodalom", "az egyiptomi Óbirodalom", "a Makedón Birodalom"], correctIndex: 0, explanation: "Hammurapi az i. e. 18. században az Óbabiloni Birodalom legjelentősebb uralkodója volt, Babilonból kormányzott. Perzsia és Makedónia jóval később emelkedett fel." },
  { id: "g09-history-020", grade: 9, subject: "history", tier: 1, prompt: "Milyen írással vésték kőbe Hammurapi törvényeit?", options: ["görög betűkkel", "ékírással", "rovásírással", "hieroglifákkal"], correctIndex: 1, explanation: "A törvényoszlop szövege akkád nyelvű, ékírással készült. A hieroglifa az egyiptomiak írása volt, a görög ábécé pedig később alakult ki." },
  { id: "g09-history-021", grade: 9, subject: "history", tier: 1, prompt: "Melyik fáraó sírjaként épült a gízai nagy piramis?", options: ["Kleopátra", "Tutanhamon", "Kheopsz", "II. Ramszesz"], correctIndex: 2, explanation: "A gízai nagy piramis Hufu, görögösen Kheopsz fáraó sírja, az Óbirodalom IV. dinasztiája idején épült. Tutanhamon és II. Ramszesz az Újbirodalom uralkodói voltak." },
  { id: "g09-history-022", grade: 9, subject: "history", tier: 1, prompt: "Hányféle írás található a Rosette-i kövön?", options: ["négy", "kettő", "egy", "három"], correctIndex: 3, explanation: "A Rosette-i kövön ugyanaz a rendelet három írással áll: hieroglifákkal, démotikus írással és görögül. A görög szöveg segítette a hieroglifák megfejtését." },
  { id: "g09-history-023", grade: 9, subject: "history", tier: 1, prompt: "Melyik évből ismerjük az első feljegyzett olimpiai játékokat?", options: ["Kr. e. 1200", "Kr. u. 476", "Kr. e. 776", "Kr. e. 490"], correctIndex: 2, explanation: "Az első írásban rögzített olimpiai eredmény Kr. e. 776-ból való, a játékokat négyévente rendezték Olümpiában. Kr. e. 490 a marathóni csata éve." },
  { id: "g09-history-024", grade: 9, subject: "history", tier: 1, prompt: "Melyik isten tiszteletére rendezték az ókori olimpiai játékokat?", options: ["Zeusz", "Apollón", "Árész", "Poszeidón"], correctIndex: 0, explanation: "Az ókori olimpiai játékokat Zeusz tiszteletére tartották az élisi Olümpiában, ahol a főisten nagy szentélye állt." },
  { id: "g09-history-025", grade: 9, subject: "history", tier: 1, prompt: "Hány consul állt egyszerre a Római Köztársaság élén?", options: ["tíz", "három", "egy", "kettő"], correctIndex: 3, explanation: "A főhatalmon mindig kettő consul osztozott, egyéves hivatali időre. Az egy személyre szóló teljhatalom csak rendkívüli esetben, a dictator kinevezésével jött létre." },
  { id: "g09-history-026", grade: 9, subject: "history", tier: 1, prompt: "Kiket képviselt Rómában a néptribunus?", options: ["a szenátorokat", "a plebejusokat", "a rabszolgákat", "a patríciusokat"], correctIndex: 1, explanation: "A néptribunus a plebejusokat, vagyis a köznépet képviselte; csak plebejus választható meg rá, és vétójoggal megakadályozhatta a hivatalnokok intézkedéseit." },
  { id: "g09-history-027", grade: 9, subject: "history", tier: 1, prompt: "Ki volt Karthágó hadvezére a második pun háborúban?", options: ["Hannibál", "Spartacus", "Leónidasz", "Scipio"], correctIndex: 0, explanation: "A második pun háborúban (Kr. e. 218–201) Hannibál vezette Karthágó seregét Itália ellen. Scipio a római oldal hadvezére volt, aki végül legyőzte." },
  { id: "g09-history-028", grade: 9, subject: "history", tier: 1, prompt: "Melyik mai magyar város területén állt a római Aquincum?", options: ["Pécs", "Szombathely", "Sopron", "Budapest"], correctIndex: 3, explanation: "Aquincum a mai Budapest III. kerületének (Óbuda) helyén állt, 106-tól Pannonia Inferior székhelye volt. Szombathely helyén Savaria, Pécs helyén Sopianae épült." },
  { id: "g09-history-029", grade: 9, subject: "history", tier: 1, prompt: "Melyik városból költözött Mohamed Medinába 622-ben?", options: ["Damaszkuszból", "Mekkából", "Bagdadból", "Jeruzsálemből"], correctIndex: 1, explanation: "622-ben Mohamed Mekkából Medinába költözött; ezt a kivándorlást hidzsrának nevezik, és ettől számítják a muszlim naptár kezdetét." },
  { id: "g09-history-030", grade: 9, subject: "history", tier: 1, prompt: "Melyik spártai király esett el Kr. e. 480-ban Thermopülainál?", options: ["Periklész", "Szolón", "Leónidasz", "Miltiadész"], correctIndex: 2, explanation: "I. Leónidasz spártai király a thermopülai csatában esett el Kr. e. 480-ban. Periklész és Szolón athéni államférfi, Miltiadész athéni hadvezér volt." },
  { id: "g09-history-031", grade: 9, subject: "history", tier: 1, prompt: "Ki volt az ifjú Nagy Sándor tanítója?", options: ["Szókratész", "Arisztotelész", "Homérosz", "Hérodotosz"], correctIndex: 1, explanation: "II. Philipposz a filozófus Arisztotelészt bízta meg fia, Alexandrosz oktatásával. Szókratész már Sándor születése előtt meghalt." },
  { id: "g09-history-032", grade: 9, subject: "history", tier: 2, prompt: "Mit szüntetett meg Szolón „teherlerázása” Athénban?", options: ["az adósrabszolgaságot", "a királyságot", "a cserépszavazást", "az olimpiai játékokat"], correctIndex: 0, explanation: "Szolón teherlerázása (szeiszakhtheia) megszüntette az adósrabszolgaságot és elengedte az adósságokat. A cserépszavazást később Kleiszthenész vezette be." },
  { id: "g09-history-033", grade: 9, subject: "history", tier: 2, prompt: "Hány vagyoni osztályba sorolta Szolón az athéni polgárokat?", options: ["tíz", "hat", "kettő", "négy"], correctIndex: 3, explanation: "Szolón a polgárokat vagyonuk szerint négy osztályba sorolta, és ehhez kötötte a jogaikat és kötelességeiket. A tíz phülé Kleiszthenész későbbi beosztása." },
  { id: "g09-history-034", grade: 9, subject: "history", tier: 2, prompt: "Hány phülére (kerületre) osztotta Kleiszthenész Attikát?", options: ["tizenkettő", "négy", "tíz", "öt"], correctIndex: 2, explanation: "Kleiszthenész Attikát tíz phülére osztotta, és mindegyik 50 tagot küldött az ötszázak tanácsába. A négy osztály Szolón vagyoni beosztása volt." },
  { id: "g09-history-035", grade: 9, subject: "history", tier: 2, prompt: "Melyik athéni dolgozta ki a szalamiszi csata haditervét?", options: ["Kleiszthenész", "Themisztoklész", "Miltiadész", "Periklész"], correctIndex: 1, explanation: "A Kr. e. 480-as szalamiszi tengeri csata hadrendjét és stratégiáját az athéni Themisztoklész dolgozta ki; a görögök döntő győzelmet arattak." },
  { id: "g09-history-036", grade: 9, subject: "history", tier: 2, prompt: "Melyik perzsa király flottája szenvedett vereséget Szalamisznál?", options: ["Kambüszész", "III. Dareiosz", "Xerxész", "Kürosz"], correctIndex: 2, explanation: "Szalamisznál Kr. e. 480-ban Xerxész perzsa király flottája szenvedett vereséget. III. Dareiosz másfél évszázaddal később Nagy Sándor ellenfele volt." },
  { id: "g09-history-037", grade: 9, subject: "history", tier: 2, prompt: "Ki vezette az athéni sereget a marathóni csatában?", options: ["Miltiadész", "Periklész", "Themisztoklész", "Leónidasz"], correctIndex: 0, explanation: "Kr. e. 490-ben Marathónnál Miltiadész vezette az athéni sereget I. Dareiosz perzsa csapatai ellen, és az athéniak győztek." },
  { id: "g09-history-038", grade: 9, subject: "history", tier: 2, prompt: "Melyik csatában győzte le Nagy Sándor III. Dareioszt Kr. e. 331-ben?", options: ["Marathónnál", "Cannaenál", "Szalamisznál", "Gaugamélánál"], correctIndex: 3, explanation: "Kr. e. 331-ben Gaugamélánál Nagy Sándor döntő győzelmet aratott III. Dareiosz felett, ezzel véget ért az Óperzsa Birodalom. Cannae a pun háborúk csatája." },
  { id: "g09-history-039", grade: 9, subject: "history", tier: 2, prompt: "Melyik városban halt meg Nagy Sándor Kr. e. 323-ban?", options: ["Rómában", "Babilonban", "Athénban", "Alexandriában"], correctIndex: 1, explanation: "Nagy Sándor Kr. e. 323-ban, 32 évesen Babilonban halt meg. Holttestét később Alexandriába vitték, ezért ott volt a nyughelye." },
  { id: "g09-history-040", grade: 9, subject: "history", tier: 2, prompt: "Ki volt Nagy Sándor apja?", options: ["Xerxész", "III. Dareiosz", "Leónidasz", "II. Philipposz"], correctIndex: 3, explanation: "Nagy Sándor apja II. Philipposz makedón király volt, aki Arisztotelészt fogadta fia mellé tanítónak. III. Dareiosz a perzsa ellenfél volt." },
  { id: "g09-history-041", grade: 9, subject: "history", tier: 2, prompt: "Melyik hegységen kelt át Hannibál elefántjaival Itáliába?", options: ["a Kaukázuson", "a Balkán-hegységen", "az Alpokon", "a Kárpátokon"], correctIndex: 2, explanation: "Hannibál a második pun háborúban az Alpokon kelt át, és mintegy 30 elefántot vitt be Itáliába. A Kárpátok, a Balkán-hegység és a Kaukázus messze esett az útvonalától." },
  { id: "g09-history-042", grade: 9, subject: "history", tier: 2, prompt: "Melyik múzeumban őrzik ma Hammurapi törvényoszlopát?", options: ["a londoni British Museumban", "a párizsi Louvre-ban", "a kairói múzeumban", "a római Vatikánban"], correctIndex: 1, explanation: "A dioritból faragott törvényoszlopot egy francia expedíció találta meg Szúzában 1901–1902 fordulóján; ma a párizsi Louvre-ban őrzik. A British Museumban a Rosette-i kő látható." },
  { id: "g09-history-043", grade: 9, subject: "history", tier: 2, prompt: "Melyik pápa hirdette meg az első keresztes hadjáratot?", options: ["II. Orbán", "III. Ince", "Nagy Szent Gergely", "II. Szilveszter"], correctIndex: 0, explanation: "Az első keresztes hadjáratot II. Orbán pápa hirdette meg 1095-ben a clermont-i zsinaton; a főúri seregek 1096-ban indultak el." },
  { id: "g09-history-044", grade: 9, subject: "history", tier: 2, prompt: "Mi volt Spartacus, a Kr. e. 73-as felkelés vezetője?", options: ["szenátor", "consul", "néptribunus", "gladiátor"], correctIndex: 3, explanation: "Spartacus gladiátor volt; szökött társaival Kr. e. 73 és 71 között vezetett felkelést Itáliában. A consul és a szenátor a római vezetők közé tartozott." },
  { id: "g09-history-045", grade: 9, subject: "history", tier: 3, prompt: "Ki győzött a peloponnészoszi háborúban?", options: ["az Athén vezette szövetség", "a Perzsa Birodalom", "Makedónia", "a Spárta vezette szövetség"], correctIndex: 3, explanation: "A Kr. e. 431–404 közötti háborút a Spárta vezette Peloponnészoszi Szövetség nyerte; a Déloszi Szövetség felbomlott, Athén falait lerombolták." },
  { id: "g09-history-046", grade: 9, subject: "history", tier: 3, prompt: "Mikor zajlott a peloponnészoszi háború?", options: ["Kr. e. 218–201", "Kr. e. 431–404", "Kr. e. 490–479", "Kr. e. 264–241"], correctIndex: 1, explanation: "A peloponnészoszi háború Kr. e. 431–404 között zajlott Athén és Spárta szövetségei között. A Kr. e. 218–201 a második pun háború időszaka." },
  { id: "g09-history-047", grade: 9, subject: "history", tier: 3, prompt: "Melyik évben alakult meg Athén vezetésével a Déloszi Szövetség?", options: ["Kr. e. 478", "Kr. e. 404", "Kr. e. 776", "Kr. e. 594"], correctIndex: 0, explanation: "A Déloszi Szövetség Kr. e. 478-ban alakult Athén vezetésével, a perzsák elleni védekezésre. Kr. e. 404-ben, a peloponnészoszi háború végén bomlott fel." },
  { id: "g09-history-048", grade: 9, subject: "history", tier: 3, prompt: "Hová költöztette Periklész Kr. e. 454-ben a szövetségi kincstárat?", options: ["Korinthoszba", "Délosz szigetére", "Athénba", "Spártába"], correctIndex: 2, explanation: "A szövetségi kincstár eredetileg Délosz szigetén volt, Kr. e. 454-ben Periklész Athénba költöztette — a szövetség ezzel Athén birodalmává vált." },
  { id: "g09-history-049", grade: 9, subject: "history", tier: 3, prompt: "Melyik évben aratta Hannibál cannae-i győzelmét?", options: ["Kr. e. 202", "Kr. e. 264", "Kr. e. 146", "Kr. e. 216"], correctIndex: 3, explanation: "Hannibál Kr. e. 216-ban Cannaenál aratta legnagyobb győzelmét. Kr. e. 202-ben Zamánál vereséget szenvedett, Kr. e. 146-ban pedig elpusztult Karthágó." },
  { id: "g09-history-050", grade: 9, subject: "history", tier: 3, prompt: "Ki győzte le Hannibált Kr. e. 202-ben Zamánál?", options: ["Spartacus", "Scipio", "Julius Caesar", "Augustus"], correctIndex: 1, explanation: "A zámai csatában Kr. e. 202-ben a Scipio vezette római sereg legyőzte Hannibált; ez volt a második pun háború döntő csatája." },
  { id: "g09-history-051", grade: 9, subject: "history", tier: 3, prompt: "Melyik évben pusztították el a rómaiak Karthágót?", options: ["Kr. e. 146", "Kr. e. 216", "Kr. e. 31", "Kr. e. 509"], correctIndex: 0, explanation: "A harmadik pun háború végén, Kr. e. 146-ban a rómaiak elfoglalták és elpusztították Karthágót. Kr. e. 216 Cannae, Kr. e. 31 Actium éve." },
  { id: "g09-history-052", grade: 9, subject: "history", tier: 3, prompt: "Kiket győzött le Octavianus Kr. e. 31-ben Actiumnál?", options: ["Spartacust és társait", "Hannibált és Karthágót", "Antoniust és Kleopátrát", "a gallokat"], correctIndex: 2, explanation: "Actiumnál Octavianus, a későbbi Augustus, legyőzte Antoniust és Kleopátrát, akik egyesített flottával harcoltak; ezzel nyílt út a principatus kiépítéséhez." },
  { id: "g09-history-053", grade: 9, subject: "history", tier: 3, prompt: "Ki fosztotta meg trónjától 476-ban Romulus Augustulust?", options: ["Odoaker", "Nagy Károly", "Attila", "Justinianus"], correctIndex: 0, explanation: "476-ban a germán zsoldosvezér Odoaker megfosztotta trónjától Romulus Augustulust, akit a legtöbb történész az utolsó nyugatrómai császárnak tart." },
  { id: "g09-history-054", grade: 9, subject: "history", tier: 3, prompt: "Melyik évben osztották fel a verduni szerződéssel a Frank Birodalmat?", options: ["800", "476", "843", "1096"], correctIndex: 2, explanation: "A verduni szerződést 843-ban kötötték meg Nagy Károly unokái, és a Frank Birodalmat három részre osztották. 800 Nagy Károly császárrá koronázásának éve." },
  { id: "g09-history-055", grade: 9, subject: "history", tier: 3, prompt: "Hogyan nevezték a hűbérbirtokot kapó, katonai szolgálattal tartozó személyt?", options: ["néptribunus", "jobbágy", "hűbérúr", "vazallus"], correctIndex: 3, explanation: "A hűbérbirtokkal megadományozott személy a hűbéres, más néven vazallus, aki főleg katonai szolgálattal tartozott a birtokot adó hűbérúrnak." },
  { id: "g09-history-056", grade: 9, subject: "history", tier: 3, prompt: "Melyik évben foglalták el a keresztesek Jeruzsálemet?", options: ["1095", "1099", "1096", "1204"], correctIndex: 1, explanation: "Az első keresztes hadjárat seregei 1099. július 15-én foglalták el Jeruzsálemet. 1095 a clermont-i zsinat, 1096 a főúri seregek indulásának éve." },
  { id: "g09-history-057", grade: 9, subject: "history", tier: 3, prompt: "Ki fejtette meg 1822-ben az egyiptomi hieroglifákat?", options: ["Napóleon", "Champollion", "Hérodotosz", "Arisztotelész"], correctIndex: 1, explanation: "Jean-François Champollion 1822-ben a Rosette-i kő segítségével fejtette meg a hieroglifákat; a kő görög szövege adta a kulcsot." },
];
